// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_7: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.fortissimo-composition","name":"Fortissimo Composition","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["bard","concentrate","focus","spellshape"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon your muse to greatly increase the benefits you provide with your courageous anthem, rallying anthem, or song of strength composition. If your next action is to cast one of these compositions, attempt a performance check. The DC is usually the highest Will DC of the composition's targets, but the GM can assign a different DC based on the circumstances. The effect of your composition depends on the result of your check.\n\nCritical Success The status bonus from your composition increases to +3.\n\nSuccess The status bonus from your composition increases to +2.\n\nFailure Your composition provides only its normal bonus of +1, but you don't spend the Focus Point for casting this spell.","source":{"provider":"PAIZO","sourceId":"kF0rs9mCPvJGfAZE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.foul-miasma","name":"Foul Miasma","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","disease","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature affected by a disease","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You multiply the disease within a creature, drawing it into an infectious mist outside their body where it can spread to other creatures. The target must attempt a Will save. If the target is willing, it can choose to take the effects of critical failure.\nCritical Success The target receives the benefit of a successful save against the lowest-level disease affecting it.\n\nSuccess The target is unaffected.\n\nFailure One randomly chosen disease affecting the target fills the air in a centered on the target. For the spell's duration, any creature that enters or ends its turn within the area is exposed to that disease.\n\nCritical Failure As failure, except the miasma contains all the diseases affecting the target.","source":{"provider":"PAIZO","sourceId":"6nTBr5XNuKOuPM5m","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.garden-of-death","name":"Garden of Death","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":["consecration","plant","poison"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"water infused with a dozen deadly toxins worth a total of 50 gp"},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":40}},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Crafting, Medicine","secondaryCasters":2},"description":"Typically associated with the less friendly fey or druids, this ritual calls all the poisonous, toxic, and venomous plants and animals of an area to congregate in a certain place, creating a beautiful but extravagantly deadly garden.\n\nYou and the secondary casters sprinkle the ground of the garden with water infused with various poisons and a few drops of your blood. Within the bounds of the ritual, the ecosystem attracts every possible poisonous plant or animal native to the environment, with nonpoisonous plants or animals growing only if there's no toxic counterpart. This deadly ecosystem flourishes, if at all possible (plants still need light and water, for instance), for a year and gradually disperses after this period. If this ritual is successfully cast on the grounds of an existing garden of death, it resets the duration and expands the garden's radius by 20 feet instead.\n\nThe maximum level of plants or animals called by the ritual is equal to its spell rank, and the called plants and animals can use the ritual's spell DC instead of their own poison DC, whichever is higher. The garden's residents don't willingly use their poison on you or the secondary casters, but you don't otherwise control or command them.\n\nCritical Success A poisonous garden forms, and you and the secondary casters gain a +2 circumstance bonus to Nature or Crafting checks to deal with the plants or animals, such as feeding them or harvesting poison from them.\n\nSuccess As critical success, but without the circumstance bonus when interacting with the garden.\n\nFailure The ritual has no effect.\n\nCritical Failure You and the secondary casters are each bitten by the most poisonous creature found naturally in the environment.","source":{"provider":"PAIZO","sourceId":"nEXkk85BQu1cREa4","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ghostly-tragedy","name":"Ghostly Tragedy","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","spirit"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"This spell compels local spirits to reenact a violent event of the recent past that you're aware of and name as you Cast the Spell. You take the role of the primary victim. The reenactment plays out the final 9 minutes leading up to the death or injury of the victim and the minute after. The spirits don't change form, so this doesn't help determine perpetrators by their looks. Spiritual forms of missing creatures necessary for the event manifest as needed, and missing items appear as shadowy outlines.\n\nOnce the scene ends, you take 2d6[void] damage for each ghostly apparition that participated in the scene (typically equal to the number of creatures involved other than the victim). Any creature that observed the ghostly recreation, including you, can attempt checks to investigate the event to discover new clues and information.","source":{"provider":"PAIZO","sourceId":"WVc30DGbM7TRLLul","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ghostly-transcription","name":"Ghostly Transcription","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Glowing letters assemble in the air, providing a transcription of the target's speech in all languages you speak. For the spell's duration, any words spoken aloud by the target are spelled out in letters in front of them.\n\nWhen you Cast the Spell, you can choose whether these letters are visible to all creatures or only certain creatures you specify. Any words the target mouths silently are similarly spelled out, allowing the target to communicate silently or in areas where sound doesn't carry. This even allows the target to utter the incantations necessary for spells in such areas, but only if you choose to make the letters visible to all creatures.\n\nFurthermore, any of the target's auditory abilities can affect creatures even in areas where sound doesn't carry as long as you have made the glyphs visible to them and they have line of sight to the target; in this case, they gain the visual trait. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"vhe9DduqaivMs8FV","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.girzanjes-march","name":"Girzanje's March","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["auditory","concentrate","linguistic","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sing a prayer for war, inspiring valor in allies who hear your song. Allied creatures who can hear and understand you gain a +1 status bonus to attack rolls, Fortitude saves, and Will saves against mental effects.\n\nHeightened (7th) The status bonus increases to +2.\n\nHeightened (10th) The status bonus increases to +3.","source":{"provider":"PAIZO","sourceId":"pLEhF3f7KRxFo0vp","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.glass-form","name":"Glass Form","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant the target properties of dull, transparent glass. The target becomes , has no scent, and can't bleed. They gain resistance 5 to acid, cold, electricity, and piercing damage and weakness 5 to sonic and bludgeoning damage. A creature in this form is affected by the shatter spell as though the creature were an unattended object. Each time the target takes damage to which the spell grants resistance or weakness, reduce the duration by 1 minute.\n\nHeightened (+2) The resistances and weaknesses increase by 5.","source":{"provider":"PAIZO","sourceId":"3qz32XdiugYhsr32","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.glimpse-the-truth","name":"Glimpse the Truth","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","focus","manipulate","revelation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Divine insight lets you see things as they are, unveiled by attempts to magically cloak the truth. The GM attempts a secret counteract check against each illusion that is at least partially within the area. Instead of counteracting the illusion, you see through it (for instance, if the check succeeds against an spell, you see the creature's true form but illusory disguise doesn't end). Each time a new illusion comes into the aura during the duration of the spell, the GM attempts a secret counteract check for that illusion.\n\nHeightened (7th) You can allow everyone within range of the emanation to see through illusions you succeed against, not just yourself.","source":{"provider":"PAIZO","sourceId":"ZjbVgIIqMstmdkqP","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.grasp-of-the-deep","name":"Grasp of the Deep","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","mental","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"1Yh5PCqtUHHVKkOd","formula":"6d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You grip one target with the phantasmal pressure of the deep sea, disorienting and crushing its lungs and joints. The target takes 6d6 bludgeoning damage and other effects, depending on its Will saving throw.\n\nCritical Success The creature is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage, and feels as though it's being crushed. The target also becomes , but it can attempt to with an Escape DC equal to your spell DC.\n\nCritical Failure As failure, but the target takes double damage.\n\nHeightened (6th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"rwWtpZpkNYvypknx","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.grasping-earth","name":"Grasping Earth","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"YRYbZTnIe7w9wHLU","formula":"1d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"YRYbZTnIe7w9wHLU":"1d6"}},"counteraction":false,"ritual":null,"description":"Handlike protrusions of rock and soil grab and bury creatures. Each creature in the area when you cast the spell, and each creature that ends its turn in the area during the spell's duration, must attempt a Fortitude save. The first time each round you Sustain this spell, each creature still by the earth takes 1d6[bludgeoning] damage, and each creature by the earth takes 2d6[bludgeoning] damage. A creature can attempt to , rolling against your spell DC.\n\nSuccess The creature is unaffected.\n\nFailure The creature is grabbed by the earth.\n\nCritical Failure The creature is restrained by the earth.\n\nHeightened (+2) The bludgeoning damage dealt when you Sustain this spell increases by 1d6 for grabbed creatures and 2d6 for restrained creatures.","source":{"provider":"PAIZO","sourceId":"Wpgt5TYcTHLDei6J","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.holy-cascade","name":"Holy Cascade","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","holy","manipulate","water"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"one vial of holy water"},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You call upon sacred energy to amplify a vial of , tossing it an incredible distance. It explodes in an enormous burst that deals 3d6 bludgeoning damage to creatures in the area from the cascade of water. The water deals an additional ((@item.level*2)-2)d6[spirit] damage to creatures with the unholy trait in the area.\nHeightened (+1) The bludgeoning damage increases by 1d6, and the additional spirit damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"DZ9bzXYqMjAK9TzC","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.honeyed-words","name":"Honeyed Words","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Falsehoods pass your lips as smoothly as silk. You gain a +4 status bonus to Deception checks to and against Perception checks to discern if you are telling the truth, and you add your level even if untrained. If the implausibility of your lies prompts a circumstance penalty or a DC increase, reduce that penalty by half or increase it by half.","source":{"provider":"PAIZO","sourceId":"JyxTmqjYYn63V5LY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hydraulic-torrent","name":"Hydraulic Torrent","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"8d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A swirling torrent of water manifests along a straight line, battering creatures and unattended objects in its path and possibly pushing them away from you. The torrent deals 8d6 bludgeoning damage. Each creature in the area must attempt a basic Fortitude save; unattended objects automatically fail. Creatures and objects that fail are also knocked back 5 feet (10 feet on a critical failure).\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"Y3G6Y6EDgCY0s3fq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ice-storm","name":"Ice Storm","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"wnlxzlrxtrkk2bh3","formula":"2d8","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8","wnlxzlrxtrkk2bh3":"1d8"}},"counteraction":false,"ritual":null,"description":"You create a gray storm cloud that pelts creatures with an icy deluge. When you Cast the Spell, a burst of magical hail deals 2d8 bludgeoning damage and 2d8 cold damage to each creature in the area below the cloud (basic Reflex save). Snow and sleet continue to rain down in the area for the remainder of the spell's duration, making the area difficult terrain. Any creature that ends its turn in the storm takes (floor(@item.level/2))[cold] damage. If you Cast this Spell outdoors, you can create two nonoverlapping clouds instead of one. As normal, if a Large or larger creature is in both clouds, it still only takes the initial damage once and the continuing damage once per turn.\nHeightened (+2) The initial bludgeoning damage and cold damage increase by 1d8 each, and the cold damage creatures take at the end of their turns increases by 1.","source":{"provider":"PAIZO","sourceId":"kHyjQbibRGPNCixx","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.implement-of-destruction","name":"Implement of Destruction","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","emotion","fear","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 enemy, and 1 weapon that is either unattended or wielded by you or a willing ally","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You solemnly declare that the target weapon will bring death to a foe, implanting an irrational fear of the weapon into the target enemy's mind. This link echoes at the forefront of the enemy's mind, forming a looming sense of omnipresent dread. The effect is based on the target enemy's Will save.\nCritical Success The target enemy is unaffected.\n\nSuccess The target weapon deals an additional 2d6[mental] damage the first time it hits the target enemy before the end of the spell's duration.\n\nFailure The target weapon deals an additional 2d6[persistent,mental] damage to the target enemy. If the enemy is critically hit by the weapon, the enemy is Doomed 1 for as long as it takes this persistent mental damage.\n\nCritical Failure The target weapon deals an additional 4d6[persistent,mental] damage to the target enemy. If the enemy is critically hit by the weapon, the enemy is doomed 1.\nHeightened (+2) Increase the mental damage by 1d6 on a success, and increase the persistent mental damage by 1d6 on a failure or by 2d6 on a critical failure.","source":{"provider":"PAIZO","sourceId":"sUvTGELaggrBSgGm","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.inevitable-destination","name":"Inevitable Destination","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you and 1 enemy","area":null},"duration":{"text":"2 rounds","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You twist the paths of the target, ensuring that each one leads to you. The target attempts a Will saving throw.\n\nCritical Success The spell has no effect.\n\nSuccess Your pull hampers the target's footsteps. It takes a –10-foot circumstance penalty to its Speeds until the end of its next turn.\n\nFailure The target can't move any farther from you than it was when you Cast the Spell, though it can move in such a way that it maintains an equal distance. If you move farther away from the target than the initial distance, the spell ends. The targeted foe can attempt to against your spell DC. If it succeeds, the spell ends.\n\nCritical Failure As failure, plus the target is pulled 10 feet closer to you and falls , tripping in its haste to move toward you.","source":{"provider":"PAIZO","sourceId":"fMnjP4hpNRV9EfVM","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.infectious-melody","name":"Infectious Melody","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["auditory","concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"enemies in the area","area":{"shape":"EMANATION","feet":15}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth the chords of a tune so catchy that foes hearing it can't help but sing along, making it harder for them to communicate. Each target must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess For 1 round, the creature can communicate only by singing along to the melody. It can speak only on its turn, and it must take the action when it does. The result of the Performance check determines how well it sang, but it stills communicate the information regardless of the result, which has no further mechanical impact than the time spent to take the action. A single Perform check is sufficient for any amount of speaking on the creature's turn. This effect might interfere with verbal components of spells or other linguistic abilities that rely on precise speech; in order to use such an ability successfully, the creature must succeed at a flat.\n\nIn addition, the creature takes a -2 status penalty on linguistic Intimidation checks, as singing its threats saps away some of the menace. The creature's constant humming of the tune also makes it nearly impossible for the creature to remain .\n\nFailure As success, but the duration is 3 rounds.\n\nCritical Failure As success, but the duration is 1 hour.","source":{"provider":"PAIZO","sourceId":"mUz3wqbMQ5JQ06M5","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.infiltrators-tunnel","name":"Infiltrator's Tunnel","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"60 feet (see text)"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"It's best to know the ingress and egress points for any location you plan to rob. But it's even better to make your own! You create two portals. One appears on a flat surface you can touch, and the other appears on a different flat surface in range that you can see.\n\nYou can move through the portals as though they were adjacent to each other. Any other creature attempting to move through the portals must succeed at a Will saving throw or be teleported up to 30 feet away from their starting point to a random safe space determined by the GM.\nHeightened (6th) When you Cast the Spell, you can designate up to 5 other creatures to freely move between the portals.","source":{"provider":"PAIZO","sourceId":"U5dw9SiuVcLmdHoi","book":"Pathfinder NPC Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.interdisciplinary-incantation","name":"Interdisciplinary Incantation","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within 30 feet casts an arcane spell.\n\nYou gather the embers of another caster's spell, using your understanding of unified magic to pick apart their formulas and incantations well enough to imitate the spell yourself, if only for a short time. Until the end of your next turn, you can Cast the triggering Spell by expending a wizard spell slot of the same rank. That caster's spells can't trigger your interdisciplinary incantation again for 24 hours.","source":{"provider":"PAIZO","sourceId":"sGenGMmE1ntkXCtN","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.internal-insurrection","name":"Internal Insurrection","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","disease","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You afflict the target with the supernatural disease known as internal insurrection, causing portions of their body to rebel against the whole, leading to painful agonies and, in time, death. The target must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target becomes for 1 round as pain wracks their body.\n\nFailure The target is afflicted with internal insurrection at stage 1.\n\nCritical Failure The target is afflicted with internal insurrection at stage 2.\n\nInternal Insurrection (disease); Level 7.\n\nThe target can't recover from the clumsy condition from internal insurrection until the disease is cured\n\nStage 1 Clumsy 1 (1 day)\n\nStage 2 Clumsy 2 (1 day)\n\nStage 3 clumsy 2 and (1 day)\n\nStage 4 Clumsy 3 and off-guard (1 day)\n\nStage 5 death, and the target's body splits apart into a mass of fragments that crawls outward in a 10-foot-emanation before perishing, leaving a bare skeleton surrounded by gore.","source":{"provider":"PAIZO","sourceId":"RbORUmnwlB8b3mNf","book":"Pathfinder Adventure: Malevolence","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.invisibility-cloak","name":"Invisibility Cloak","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","illusion","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You become , with the same restrictions as the 2nd-rank spell.\n\nHeightened (6th) The duration increases to 10 minutes.\n\nHeightened (8th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"Nun72GTmb31YqSKh","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.invisibility-curtain","name":"Invisibility Curtain","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a transparent invisible wall that makes any creatures on one side of the wall invisible to those on the other side. You choose which side of the wall provides invisibility to the creatures on that side when you cast the spell. You create either a 1-inch-thick wall in a straight line up to 60 feet long and 10 feet high or a 1-inch-thick, 10-foot-radius ring with the same height. The wall is intangible and stands vertically in either of the two forms. If you wish to do so, you can create the wall with a shorter length or height, or with a smaller radius. Any creature that crosses the wall becomes visible or invisible as appropriate, and it's visible if any portion of it is on the visible side of the wall. If a creature rendered invisible by the wall takes a hostile action, the spell ends after the hostile action is completed.\n\nHeightened (7th) The spell doesn't end if an invisible creature takes a hostile action.","source":{"provider":"PAIZO","sourceId":"a8xXWCQhIR7o6IvP","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.isolation","name":"Isolation","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","illusion","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a tangible manifestation of loneliness to cloak the target from view as surely as if it were wreathed in darkness. The target attempts a Will saving throw.\n\nCritical Success The target is unaffected.\n\nSuccess The target becomes , but only to its allies. Any creature not allied with the target can see it normally. Effects such as enable an ally to see the target. The target's allies still know the target is present and can still see all the effects of the target's actions.\n\nFailure As success, except the target also becomes inaudible to its allies and imperceptible to them through any other senses.","source":{"provider":"PAIZO","sourceId":"mer4V7vWdTs1oLbG","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.it-is-written","name":"It is Written","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","mythic","prediction"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You envision a future for yourself, confident in the certainty that this vision is your destiny. Before the duration ends, if you would attempt an attack roll, Perception check, saving throw, or skill check that would aid in the fulfillment of this destiny, you can attempt this roll at mythic proficiency. You choose which roll to use this benefit on before rolling. If you use this benefit, the spell ends. Either way, you're then temporarily immune to it is written for 1 hour.","source":{"provider":"PAIZO","sourceId":"AXpqBdbQ66RWyZYk","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.know-the-enemy","name":"Know the Enemy","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","fortune","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You roll initiative and can see a creature, you succeed at an attack roll against a creature, or a creature fails a saving throw against one of your spells.\n\nYou quickly remind yourself of useful information. Use a Recall Knowledge action, rolling the appropriate skill check to identify the triggering creature's abilities. You can roll your check twice and use the better result.","source":{"provider":"PAIZO","sourceId":"l6zjNysNedpJcmDT","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.life-siphon","name":"Life Siphon","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You expend one of your wizard spell slots to cast a wizard spell of the necromancy school.\n\nYou use some of the spell's magic to heal yourself, regaining 1d8 Hit Points per rank of the spell.","source":{"provider":"PAIZO","sourceId":"zvvHOQV78WKUB33l","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.life-draining-roots","name":"Life-Draining Roots","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"tjnUaEqiXvjlMzf3","formula":"8d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"tjnUaEqiXvjlMzf3":"2d6"}},"counteraction":false,"ritual":null,"description":"Thorny roots erupt from your hands in a tangled cascade, puncturing creatures in the way of their growth and revitalizing you. You deal 8d6 piercing damage to creatures in the line (basic Reflex save). You gain 1d4 temporary Hit Points for every living creature in the line, as the roots transfer nutrients from those damaged into you. The temporary Hit Points last for 1 minute.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"FHfrCABOmGVaEpPx","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.lifes-flowing-river","name":"Life's Flowing River","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a flowing river of ghostly water and that sheds dim light for 10 feet on each side. The river begins in an adjacent square to you and extends in a straight 5-foot path to its maximum range or until it hits a solid barrier, whichever comes first. A creature that begins its turn in the glowing waters of the river or who enters one of the river's spaces must attempt a Will save. If the creature is undead or a nindoru, it takes 4d6[mental] damage, modified by the result of their Will save.\nCritical Success The creature ignores the river's effects until the start of its next turn. If the creature is undead or a nindoru, it takes no damage.\n\nSuccess The creature treats all squares occupied by the river as difficult terrain until the start of its next turn. If the creature is undead or a nindoru, it takes half damage.\n\nFailure As success, but the creature is also knocked . If the creature is undead or a nindoru, it takes full damage.\n\nCritical Failure As failure, but the creature is pushed 20 feet along the river's path in the direction of flow. If the creature is undead or a nindoru, it takes double mental damage.\nHeightened (+1) The mental damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"CgekONDD5jIxL8oM","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lifes-fresh-bloom","name":"Life's Fresh Bloom","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":20}},"duration":{"text":"5 rounds","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"gcU9LYuQezmqqIr2","formula":"1d6","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The ground around you blooms with life, sprouting sparkling grass, flowers, and small shrubs. Each living and non-nindoru creature that starts its turn standing on the ground in the area recovers 1d6 Hit Points and gains a +5-foot status bonus to its Speed until the end of its next turn. Nindoru fiends and undead that start their turn in the area of life's fresh bloom instead become Sickened 1 unless they succeed at a Fortitude saving throw.\n\nHeightened (7th) Increase the Hit Points restored to 1d8 and Sickened 2.\n\nHeightened (10th) Increase the Hit Points restored to 1d10 and Sickened 3.","source":{"provider":"PAIZO","sourceId":"2TVc8NabmGpc092W","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.liminal-doorway","name":"Liminal Doorway","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","extradimensional","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw a chalk doorway on an unbroken surface, which opens into an extradimensional space. Any creature treating the drawing as an actual door can Interact to touch the doorknob and pass through. The warped, chalk-drawn room beyond the door is 20 feet in width, depth, and height. The space is unadorned and empty, with chalk lines indicating the corners of the walls.\n\nIf the drawing is scrubbed away, the underlying surface is broken, or a creature attempts to enter the space that would put it over capacity, the space begins to collapse. The space ejects one creature at random each round, depositing it on the nearest open ground, until all creatures are returned outside.","source":{"provider":"PAIZO","sourceId":"OM5NeD7a1CYNqy8S","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.localized-quake","name":"Localized Quake","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","earth","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You shake the earth, toppling nearby creatures. Choose whether the spell's area is a 15-foot emanation or a 15-foot cone when you cast it. Each creature in the area standing on solid ground takes 4d6 bludgeoning damage with a basic Reflex saving throw. A creature that fails its save also falls prone.\n\nHeightened (+1) Increase the damage by 2d6.","source":{"provider":"PAIZO","sourceId":"cBUuG1yJHGeKffpg","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.lucky-break","name":"Lucky Break","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","fortune"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You fail, but don't critically fail, a saving throw.\n\nReroll the saving throw and use the better result. You then become temporarily immune for 10 minutes.","source":{"provider":"PAIZO","sourceId":"7OwZHalOdRCRnFmZ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.luring-wail","name":"Luring Wail","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["auditory","concentrate","incapacitation","manipulate","mental"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You emit a plaintive cry to lure your enemies closer. Each creature in the emanation that can hear you must attempt a Will save. If you speak a creature's name as part of the casting of the spell, that creature takes a –2 circumstance penalty to its saving throw. Each creature that enters the area on its turn must attempt a save. If you attack or take a hostile action, the condition ends only for the creature that's attacked.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Slowed 1 for 1 round.\n\nFailure The creature becomes fascinated and compelled to move toward the sound of your cry on its turn. As long as it is in the emanation and can hear, it must spend at least one of its actions on each of its turns to move closer to you.\n\nCritical Failure As failure, but the creature must spend all its actions moving toward the sound. Additionally, the creature is .","source":{"provider":"PAIZO","sourceId":"Lr737SofpsFtLpEo","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magic-mailbox","name":"Magic Mailbox","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"TOUCH"},"target":"2 containers, each no larger than 5 feet in any dimension","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an interdimensional link between two containers, both of which must be capable of being closed in such a way that their contents aren't visible. If both containers are left closed for 10 consecutive minutes, the contents of each one, totaling no more than 3 Bulk of nonliving, non-magical material per container, transport to the other's location.\n\nIf a container's contents total more than 3 Bulk, the transport fails. If either container is opened before the full 10 minutes have elapsed, the contents appear as they did when the containers were closed, and the process starts anew as soon as both containers have been closed. After the contents of the containers successfully swap, they can't swap again until after both containers have been opened at least once. Both containers must be located on the same plane for the process to function; if this ceases to be the case or if something else disrupts the effect during an active transposition, the process halts as if one of the containers had been opened.","source":{"provider":"PAIZO","sourceId":"f9duI5d8xNYqxI8d","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.malignant-sustenance","name":"Malignant Sustenance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","void"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing undead creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You embed a seed of void energy in an undead creature, restoring its unnatural vigor. The target gains fast healing 7.\n\nHeightened (+1) The fast healing increases by 2.","source":{"provider":"PAIZO","sourceId":"qzsQmpiQodHBBWYI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mantis-form","name":"Mantis Form","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You become a mantis. You gain the effects of , heightened to mantis form's level, and you can only transform into a mantis.","source":{"provider":"PAIZO","sourceId":"bKDsmKVosexwJ80i","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mantiss-grasp","name":"Mantis's Grasp","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"Orj0nFMXwcULkl5B","formula":"8d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You cause red, ghostly mantis arms to sprout from a nearby surface and crush a creature, dealing 8d6 force damage and attempting to pin the target in place. The effects are determined by the creature's Reflex save.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage and is for 1 round.\n\nCritical Failure The target takes double damage and is immobilized for 1 minute. At the end of each of its turns, the target can attempt to . The Escape DC is equal to your spell DC.\nHeightened (7th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"Tl1QAqre7H0sQEXt","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.mercurial-stride","name":"Mercurial Stride","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","metal","poison"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"sekWqUllit48HRC4","formula":"6d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"sekWqUllit48HRC4":"1d6"}},"counteraction":false,"ritual":null,"description":"Your form ripples as you take on the fluidity and toxicity of quicksilver. You partially shift into a liquid metal form and Stride up to twice your speed. During this movement, you can pass through one creature's space—without needing to attempt a check to —by splitting into droplets of mercury and reforming on the other side, though you can't end your turn in such a space. Passing through a creature's space in this way exposes it to mercury poisoning, with a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target becomes Sickened 1.\n\nFailure The target becomes Sickened 2 and takes (@item.level+2)d6[poison] damage.\n\nCritical Failure The target becomes Sickened 2 and takes ((@item.level+2)*2)d6[poison] damage.\n\nHeightened (+1) The damage increases by 1d6 on a failure and 2d6 on a critical failure.","source":{"provider":"PAIZO","sourceId":"ma3sndEAZdz0Cy2H","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.mirage","name":"Mirage","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":50}},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusion that causes natural terrain to look, sound, feel, and smell like a different kind of terrain. This doesn't disguise any structures or creatures in the area.\n\nAny creature that touches the illusion or uses the action to examine it can attempt to disbelieve your illusion.\n\nHeightened (5th) Your image can also disguise structures or create illusory structures (but still doesn't disguise creatures).","source":{"provider":"PAIZO","sourceId":"HBJPsonQnWcC3qdX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mirrors-misfortune","name":"Mirror's Misfortune","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You split into your real self and a mirrored version of yourself that curses would-be attackers with misfortune on their next attacks. When you cast this spell, you seem to split in two. As you do, you can Step to any adjacent square. In either your initial square, or another square adjacent to your initial square, an exact illusory duplicate of you appears. You decide a simple course of action for the duplicate to follow, such as to walk to a specific point or wave its hands in the air, but more complex routines are beyond its abilities. A creature can distinguish between you and the duplicate only if it spends an action to Seek and succeeds at a Perception check against the spell's DC.\n\nIf a creature takes a hostile action against the duplicate, the illusion shatters into mirrorlike shards, inflicting bad luck on the attacker's next few attacks as misfortune's toll for shattering the mirror. The attacker must attempt a Will save with the following effects; this is a curse and misfortune effect. When the duplicate shatters, the spell ends.\n\nSuccess The creature is unaffected.\n\nFailure Within the next hour, the creature must roll its next two attack rolls twice and take the lower result.\n\nCritical Failure Within the next hour, the creature must roll its next four attack rolls twice and take the lower result.","source":{"provider":"PAIZO","sourceId":"A7w3YQBrFNH8KYsB","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.misty-memory","name":"Misty Memory","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"target":"1 body of water of at least 5 square feet","area":null},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Some say water holds memories or impressions of the past, and you can raise those memories to the surface to glimpse recent events. When you Cast the Spell, you fix your mind on an amount of time in the past, up to 24 hours ago. A mist rises from the target body of water, filling a and coalescing into a misty scene of the events that took place at that time within 60 feet of the water.\n\nAny creature who can see the area can observe the images produced, which are a translucent white color and detailed enough to show a silhouette, outline, or contour of creatures and objects that passed through the area and the motions they took. Fine details, such as facial features or written letters, are too precise for the mist to form, and the scene is silent.\n\nYou can Sustain the spell to cause the mist to play events backward or forward, with each minute spent Sustaining corresponding to a minute of playback.\n\nStrong winds from a magical source can disrupt this spell if the effect succeeds at a counteract check against your spell DC.","source":{"provider":"PAIZO","sourceId":"zu40ATlcCjtfWBnj","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.morass-of-ages","name":"Morass of Ages","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["aura","concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself in temporal eddies that draw out time for those around you, making every step feel like an eternity endured. A creature in the emanation, or that later enters the emanation, must attempt a Fortitude save. The creature attempts this save only once and uses the same effect for the duration of the spell. Each time you Sustain the Spell, you can choose to increase the emanation's radius by 5 feet, to a maximum of 60 feet.\nCritical Success The creature is unaffected.\n\nSuccess Squares in the area are difficult terrain for the creature.\n\nFailure Squares in the area are difficult terrain for the creature, and the creature is Slowed 1 when it starts its turn in the area.\n\nCritical Failure As failure, plus the creature also becomes . The creature can attempt to Escape against your spell DC to remove the restrained condition.","source":{"provider":"PAIZO","sourceId":"D6BcAoWFxHYTKwVZ","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mountain-resilience","name":"Mountain Resilience","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"20 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's skin hardens like the stone of a mountain face. It gains resistance 5 to physical damage, except adamantine. Each time the target is hit by a bludgeoning, piercing, or slashing attack, mountain resilience's duration decreases by 1 minute.\n\nHeightened (6th) The resistance increases to 10.\n\nHeightened (8th) The resistance increases to 15.\n\nHeightened (10th) The resistance increases to 20.","source":{"provider":"PAIZO","sourceId":"2BV2yYPfVJ5zirZt","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.movanic-glimmer","name":"Movanic Glimmer","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","good","manipulate","mental"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 animal","area":null},"duration":{"text":"until you next perform your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You give the target animal a glimmer of awareness, not truly awakening it but allowing it to better understand its surroundings. The target gains a +2 status bonus to Perception checks and Will saves, and any Nature checks to Command the target Animal gain a +1 status bonus from its increased understanding. Additionally, if the target animal has the minion trait, it can take one action each turn even if its master doesn't use an action to Command it, which it can use to perform any basic action it knows. This doesn't prevent a target that was summoned from disappearing if its summoner doesn't Sustain the Spell, but does allow the target to perform one action before disappearing.\n\nHeightened (8th) You can target up to 5 animals.","source":{"provider":"PAIZO","sourceId":"e9tVGZhYW37CtbHA","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.murderous-vine","name":"Murderous Vine","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["attack","concentrate","manipulate","plant","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature adjacent to a flat surface","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"2d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6","1":"1d8"}},"counteraction":false,"ritual":null,"description":"You summon a slithering, thorny vine that attempts to constrict and crush a foe against a wall or other surface. Make a spell attack roll against the target's Fortitude DC. On a success, the creature is grabbed and takes 3d6 bludgeoning damage and 2d8 piercing damage. At the end of that creature's turn, if it's still grabbed by the vine, it takes (floor(@item.level/2))d6[bludgeoning] damage.\n\nThe vine's Escape DC is equal to your spell DC. A creature can attack the vine in an attempt to break its grip. The vine's AC is equal to your spell DC, and the vine is destroyed if it takes 20 or more damage. Destroying or escaping from the vines ends the spell. You can Dismiss the spell.\nHeightened (+2) The initial bludgeoning damage increases by 1d6, the initial piercing damage increases by 1d8, and the damage a creature takes for ending its turn grabbed by the vine increases by 1d6.","source":{"provider":"PAIZO","sourceId":"kCgkreCT6g0dipMd","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.mutilate","name":"Mutilate","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"2 or 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":40},"target":"1 creature in line of sight","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"SXOGI7BFM0mUsAPF","formula":"5d8","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"SXOGI7BFM0mUsAPF":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You cut your own body in a ritualistic manner, causing similar damage to a creature in your line of sight. These cuts are superficial and cause 1d4 slashing damage to you; however, the wounds that open up on our target's body are far deeper. The targeted creature takes 5d8 slashing damage; a creature that critically fails this saving throw also takes (1d8 + @item.level -4)[bleed] damage. If you cast this as a three-action spell, the spell instead affects a 5-foot burst.\nHeightened (+1) Increase the damage dealt to the target by 1d8, and increase the persistent bleed damage by 1.","source":{"provider":"PAIZO","sourceId":"BWvGBx51RevizICD","book":"Pathfinder #209: Destroyer's Doom","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.mystic-beacon","name":"Mystic Beacon","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The next damaging or healing spell the target casts before the start of your next turn deals damage or restores Hit Points as if the spell were heightened 1 rank higher than its actual rank. This applies only to initial healing or damage when the spell is cast, not any ongoing effects. The spell otherwise functions at its actual rank. Once the target casts the spell, mystic beacon ends.","source":{"provider":"PAIZO","sourceId":"2SYq0ZTsOtJEigFx","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.natures-bounty","name":"Nature's Bounty","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate","plant","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1},"requirements":"You have a free hand."},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d10+12","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"6"}},"counteraction":false,"ritual":null,"description":"A palm-sized raw fruit or vegetable of your choice appears in your open hand. A creature can consume the food with an Interact action to regain 3d10+12 Hit Points and be nourished as if it had eaten a meal. If uneaten, the food crumbles to dust after 1 minute.\n\nHeightened (+1) The Hit Points restored increase by 6.","source":{"provider":"PAIZO","sourceId":"vSSKyUdrHu86E5Gk","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.necrotic-radiation","name":"Necrotic Radiation","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"one object or one 10-foot-square area","area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You imbue the touched object or space with slow-acting necrotic radiation. If you cast the spell on an object, any creature ending its turn holding or carrying the object takes 2d6 void damage. If you cast the spell on an area, any creature ending its turn in the area takes 2d6 void damage. You can attempt to use this spell on an attended object by touching the object. If you do, the creature attempts a Reflex save to reduce the effect.\n\nCritical Success The object is unaffected.\n\nSuccess The creature pulls the object away quickly. The spell only lasts 1 minute.\n\nFailure The creature manages to slightly protect the object. The spell lasts 10 minutes.\n\nCritical Failure The spell lasts the full 24 hours.\n\nHeightened (+2) Increase the radiation's void damage by 1d6","source":{"provider":"PAIZO","sourceId":"29p7NMY2OTpaINzt","book":"Pathfinder #154: Siege of the Dinosaurs","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.nightmare","name":"Nightmare","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 creature you know by name","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send disturbing nightmares to your target. The next time the target falls asleep, it must attempt a Will save. If you know the target only by name and have never met them, the target gets a +4 circumstance bonus to the Will save.\n\nCritical Success The target suffers no adverse effects and is temporarily immune for 1 week.\n\nSuccess The target experiences the nightmares but suffers no adverse effects other than unpleasant memories.\n\nFailure The target experiences the nightmares and awakens .\n\nCritical Failure The target experiences the nightmares, awakens Fatigued, and is Drained 2 until it is no longer Fatigued.","source":{"provider":"PAIZO","sourceId":"Uqj344bezBq3ESdq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ocular-overload","name":"Ocular Overload","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","contingency","illusion","incapacitation","manipulate","visual"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Just as a creature is about to attack you, you assault them with jarring illusions, completely surrounding their eyes with blinding flashes of motion and color. When the spell is complete, you gain the reaction; once you use the reaction, the spell ends.\n\nfortitude","source":{"provider":"PAIZO","sourceId":"HvBpSeUDg0KcK2Hg","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ordained-purpose","name":"Ordained Purpose","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You call upon the authority of cosmic forces of order, overwhelming creatures with remorse and agony for acting outside of their station and purpose.\n\nEnemies in the area take 4d6 mental damage and must attempt a Will save. A creature that has lost abilities as a result of performing acts anathema to its deity or beliefs (such as a champion who violated their tenets and hasn't atoned) uses the outcome one degree of success worse than the result of its saving throw.\n\nAt the GM's discretion, a creature currently filling its appointed station and purpose (such as a farmer working in a field or a criminal in the act of committing a crime) uses the outcome one degree of success better than the result of its saving throw.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and must as its first action on its next turn.\n\nCritical Failure The creature takes double damage, must as its first action on its next turn, and can't during its next turn.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"CPNlhDQP3aDmLzB3","book":"Pathfinder #161: Belly of the Black Whale","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.outcasts-curse","name":"Outcast's Curse","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","curse","manipulate","mental","misfortune"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You afflict the target with a curse that makes its presence abrasive and off-putting. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess For 10 minutes, the target must roll twice and use the worse result whenever attempting a Deception, Diplomacy, Intimidation, or Performance check, and creatures they encounter have an initial attitude toward them of one step worse (for instance, instead of ).\n\nFailure As success, but the effect is permanent.\n\nCritical Failure As failure, and creatures that the target encounters have an initial attitude toward them of two steps worse.","source":{"provider":"PAIZO","sourceId":"KSAEhNfZyXMO7Z7V","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.overflowing-sorrow","name":"Overflowing Sorrow","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","concentrate","emotion","focus","incapacitation","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15,"text":"15-foot emanation, centered on you"}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Sadness flows out of you into nearby creatures, blotting out any other thoughts they had. The first time a creature begins its turn in the area or enters the area, it must attempt a Will save. If it later leaves and reenters the area, it uses the same effect as before.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes a –1 status penalty to skill checks and Perception checks as long as it remains in the area.\n\nFailure While the creature is in the area, any emotion effects of lower counteract rank than overflowing sorrow are suppressed, and whenever the creature attempts to use an emotion action or cast an emotion spell, it must succeed at a flat or the action or spell is disrupted.\n\nCritical Failure As failure, but the creature can't use emotion actions or spells.\nHeightened (+2) When you Cast the Spell, you can choose to increase the area by 5 feet.","source":{"provider":"PAIZO","sourceId":"eCniO6INHNfc9Svr","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.painful-vibrations","name":"Painful Vibrations","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","sonic"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"8d6","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You send powerful sound waves through an opponent's body, vibrating its bones and internal organs painfully. The creature takes 8d6 sonic damage and must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage, is Sickened 1, and is for 1 round.\n\nCritical Failure The target takes double damage, is Sickened 2, and is deafened for 1 minute.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"qTzvVnAMWL05VitC","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.path-of-least-resistance","name":"Path of Least Resistance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You trace several possible routes, quickly resetting the timeline until you find the safest one. Choose three spaces you could reach with two Stride actions. Each must be at least 20 feet from the other two. You Stride twice to one of the spaces, determined randomly by the GM from among the paths you chose. If some of the paths contain a hidden danger, such as a trap that you would trigger by walking into the trap's affected area, the GM doesn't consider this path when randomly determining which one you take, but if all options have a hidden danger, the GM randomly chooses between all three paths. This movement doesn't trigger reactions.","source":{"provider":"PAIZO","sourceId":"s3LISC5Z55urpBgU","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.peaceful-bubble","name":"Peaceful Bubble","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"BURST","feet":100}},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"An opaque shell of drifting, iridescent runes covers the area, creating a bubble. You can choose to make the burst smaller, in 10-foot increments. The runes don't block travel, but those inside the bubble can't perceive those outside it and vice versa. Detection and scrying effects are likewise blocked.\n\nCreatures sleeping within the bubble are immune to dreams sent by spells. Those sleeping 8 hours reduce their condition by 2 instead of 1.","source":{"provider":"PAIZO","sourceId":"onjZCEHs3JJJRTD0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.perfected-body","name":"Perfected Body","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You fail or critically fail a saving throw against an effect that has the morph, poison, or polymorph trait, or that would make you , , , , or .\n\nYour body's perfection keeps you just a little bit healthier than most. You get a failure if you rolled a critical failure or a success if you rolled a failure.","source":{"provider":"PAIZO","sourceId":"8ifpNZkaxrbs3dBJ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pernicious-poltergeist","name":"Pernicious Poltergeist","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an echo of a powerful poltergeist, temporarily anchoring it to the area to terrorize and harm any opponents foolish enough to remain in the area. Because the poltergeist is a manifestation and is not truly present, it can't be attacked or hurt; it remains unless otherwise stated. When you Cast the Spell, and the first time you Sustain it on subsequent rounds, the poltergeist creates your choice of one of the following effects.\n- Deathly Assault (negative) The poltergeist focuses on one creature in the area and flies through that creature's space, dealing (4 + floor((@item.rank - 4)/2))d10[void] damage (fortitude save).\n- Frighten (emotion, fear, mental) The poltergeist becomes visible, appearing as a skeletal, ghostlike humanoid. Creatures in the area must attempt a will save, becoming Frightened 2 on a failure.\n- Telekinetic Storm (force) The poltergeist hurls debris and quasi-real objects around in the area. All creatures in the area take (4 + floor((@item.rank - 4)/2))d8[force] damage (reflex save).\nHeightened (+2) The damage of the deathly assault effect increases by 1d10, and the damage of the telekinetic storm effect increases by 1d8.","source":{"provider":"PAIZO","sourceId":"PtX16vbWzDehj8qc","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.personal-runewell","name":"Personal Runewell","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"CYLINDER","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"BvMfi3GU5iSfheEF","formula":"4d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"BvMfi3GU5iSfheEF":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area (continued) 15-foot radius, 30-foot-tall cylinder\nThe runelords of Thassilon pioneered the creation of runewells, magical artifacts that could extract and store the power of sin magic from mortal souls. A circle of light carves its way across the ground as you create your very own runewell, your personal rune flaring to life within it as you add your own sin to those seven revered in the past. Whenever any creature Casts a Spell within your personal runewell, the well resonates, with your choice of effects.\n- The runewell amplifies the power of your spells, as well as those of your allies. If the spell deals damage and doesn't have a duration, the well adds a status bonus to damage equal to the spell's rank.\n\n- The runewell punishes enemies foolish enough to attempt magic in your seat of power, firing arcane bolts at the spell's caster that deal 4d6 force damage, with a basic Reflex save.\n\nIf you cast personal runewell a second time, your previous personal runewell vanishes. You can Dismiss the spell.\nHeightened (+1) The amount of damage dealt by the runewell's bolts increases by 1d6.\nPFS Note: Within the area of a personal runewell spell, the caster chooses the effect each time a spell is cast. This can be a different effect for different spells.","source":{"provider":"PAIZO","sourceId":"N91EI7H1p7YXKX0o","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.pest-swarm","name":"Pest Swarm","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Sometimes the most common irritations can band together and become threats to your enemies. You reach out to the pests and nuisances around you, forming a small squadron of them to harass and occupy your opponents. They swarm from the forests, the air, and even the dirt beneath your feet. The pest squadron occupies the space of a Large creature, and like a swarm, they can occupy the same space as other creatures. When you Cast this Spell, choose one of the pest squadrons below to summon.\n- Cockroaches Speed 30 feet, climb 30 feet.\n- Arrive Scurrying Swarm The swarm of cockroaches scuttles toward the enemy, swarming them and climbing up the bodies of any enemy touching the ground. They deal 4d6[piercing|options:area-damage] damage (reflex save) to all enemies within their space and in a . On a critical failure, a creature can't use concentrate actions for 1 round as they try and brush away the insects.\n\n- Depart Farewell Dirt The cockroaches disperse, climbing down from the creatures and leaving behind their debris and dirt. All enemies in their space must attempt a fortitude save. On a failure, a creature is Sickened 2 (Sickened 3 on a critical failure).\n\n- Mosquitoes Speed 30 feet, fly 50 feet.\n- Arrive Biting Flight The mosquitoes arrive in a hazy cloud, landing on the exposed skin of your opponents and dealing 4d6[piercing|options:area-damage] damage to enemies in their space (reflex save).\n- Depart Parting Gift The swarm attempts to drain their opponents before flying off. All enemies in their space and in a must succeed at a fortitude save or become Drained 1 (Drained 2 on a critical failure).\n\n- Pigeons Speed 20 feet, fly 40 feet.\n- Arrive Dive Bomb The swarm of pigeons dives into the crowd of enemies and attacks with beaks and talons. Each enemy within their space takes 2d8[piercing,2d4[slashing]|options:area-damage] damage (reflex save). On a critical failure, a creature is for 1 round.\n- Depart (sonic) Wing Snap The pigeon swarm snaps their wingtips together to startle their opponents before leaving. Each enemy within their space takes 4d6[sonic|options:area-damage] damage (fortitude save).\n\n- Rats Speed 30 feet, burrow 20 feet.\n- Arrive Chittering Race Rats swarm the legs of your enemies, biting at them and digging their sharp nails into whatever exposed flesh reveals itself. Each enemy in their space takes 4d6[piercing|options:area-damage] damage (reflex save).\n- Depart Underfoot The rats scurry underfoot, tripping up enemies and burrowing underground to make a swift getaway. Each enemy in their space must succeed a reflex save or be knocked and take 2d6[bludgeoning|options:area-damage] damage. The area the rat swarm was in becomes difficult terrain for 1 round.\n\n- Skunks Speed 30 feet, climb 20 feet;\n- Arrive Mustelid Charge Skunks race to the scene, and each enemy within their space and within a take 4d6[piercing|options:area-damage] damage (reflex save) as the skunks snarl and bite.\n- Depart (acid) Stink Bomb Before leaving, the skunks launch a final offensive maneuver and release their stink glands in a . All creatures in the area take 2d6[acid|options:area-damage] damage (fortitude save). On a failure, a creature is also Sickened 1 (sickened 2 on a critical failure).\n\n- Spiders Speed 30 feet, climb 30 feet.\n- Arrive (poison) Venomous Swarm A horde of violin spiders crawls up from the ground, climbing onto enemies within their space and in a and biting them. Each enemy takes 3d6[piercing|options:area-damage] damage (fortitude save). Enemies who fail are exposed to violin spider venom.\n\n- Depart Spinning Webs As the violin spiders depart, they spray sticky webs at their enemies in a . All creatures in this cone must attempt a reflex save. On a failure, a creature takes a –10-foot circumstance penalty to their Speeds (–20-foot circumstance penalty on a critical failure) for 1 minute; a creature can remove this penalty with a successful against your spell DC. The area of the cone is also difficult terrain for 1 round.\n\nViolin Spider Venom (poison)\n\nSaving Throw fortitude\n\nMaximum Duration 6 rounds\n\nStage 1 1d6[poison|traits:poison] (1 round)\n\nStage 2 2d6[poison|traits:poison] and Clumsy 1 (1 round)\n\nStage 3 2d6 poison, 1d6[persistent,bleed], and clumsy 1 (1 round)\n\nStage 4 2d6 poison, 2d6[persistent,bleed], and clumsy 1 (1 round)","source":{"provider":"PAIZO","sourceId":"fRqHDOWmgcUTeT03","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.petal-storm","name":"Petal Storm","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate","manipulate","plant","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d10","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You bring forth a cloud of razor-sharp flower petals that thrash violently in the wind. A creature that enters the storm or starts its turn in the storm is sliced by the razor-sharp edges of the petals. It takes 2d10 slashing damage with a basic Reflex save. A creature can take damage from the petals only once per round. At the end of the duration, the storm calms and the petals fall harmlessly to the ground.\n\nHeightened (+2) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"D31YX7zvRBvenTAz","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.phantasmal-killer","name":"Phantasmal Killer","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","death","emotion","fear","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a phantasmal image of the most fearsome creature imaginable to the target. Only the spell's target can see the killer, though you can see the vague shape of the illusion as it races forth to attack. The effect of the killer is based on the outcome of the target's Will save.\nCritical Success The target is unaffected.\n\nSuccess The target takes 4d6[mental] damage and is Frightened 1.\n\nFailure The target takes (max(8,@item.rank*2))d6[mental] damage and is Frightened 2.\n\nCritical Failure The target is so afraid it might die. It must attempt a fortitude save; if the target fails, it dies. On a successful Fortitude save, the target takes (max(12,@item.rank*3))d6[mental] damage, is until the end of its next turn, and is Frightened 4. This effect has the incapacitation trait.\nHeightened (+1) The damage increases by 2d6 on a failure and by 3d6 on a critical failure.","source":{"provider":"PAIZO","sourceId":"tlcrVRqW1MSKJ5IC","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantasmal-protagonist","name":"Phantasmal Protagonist","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","illusion","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a phantasmal incarnation of a significant character from a novel, historical work, or religious parable. The phantasm is Medium, regardless of the size of the character as it was described in the inspirational work. When you Cast the Spell, decide what theme the protagonist is, choosing from hero, ally, or villain. The protagonist appears in an unoccupied space within range, and the first time each round that you Sustain the Spell, you can direct the protagonist to Stride or take the action granted by its theme. The phantasmal protagonist has a speed of 25 feet and an AC of 22. Its saving throw modifiers, Perception modifier, and skill modifiers are +12. It has 90 HP.\n\nHero: The protagonist takes the form of a legendary hero. Its thematic action is to attempt a melee Strike, using your spell attack roll to make the attack and inflicting 4d6+6 mental damage on a hit.\n\nAlly: The protagonist takes the form of a recognizable support character. Its thematic action is to grant an adjacent creature 4d4 temporary Hit Points, which last for 1 round.\n\nVillain: The protagonist takes the form of a notorious villain. Its thematic action is to harry and mock an adjacent target. The target must succeed at a Will save or become (Slowed 1 on a critical failure) until the end of your next turn.\n\nHeightened (+1) The protagonist's AC, saving throw modifiers, skill modifiers, and Perception modifier increases by 3, and its HP increase by 30. A heroic protagonist's damage increases by 1d6. An ally protagonist's temporary Hit Points granted increases by 1d4.","source":{"provider":"PAIZO","sourceId":"IKb9EOfsrhScO3GO","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phoenix-ward","name":"Phoenix Ward","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"wtPB4EA7uiVSWUKV","formula":"4d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"wtPB4EA7uiVSWUKV":"1d8"}},"counteraction":false,"ritual":null,"description":"You raise a fiery shield around yourself, gaining resistance 10 to fire. If you take fire damage that would reduce you to 0 Hit Points, the phoenix ward absorbs any damage beyond the amount that would bring you to 1 Hit Point. The ward then heals you in a brilliant display of flames in the shape of a phoenix's wings and envelop you in light. You regain Hit Points equal to 4d8 + the absorbed damage; this is a healing vitality effect. The phoenix ward then ends, and you can't cast it again for 24 hours.\n\nHeightened (+1) The healing increases by 1d8.","source":{"provider":"PAIZO","sourceId":"lJdAvY1sJyEmNDc6","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.planar-tether","name":"Planar Tether","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You stitch the target to its current plane. While the target is affected by planar tether, the spell attempts to counteract any teleportation effect that would move the target, or any effect that would transport it to a different plane. Planar tether's duration is determined by the target's Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The effect's duration is 1 minute.\n\nFailure The effect's duration is 10 minutes.\n\nCritical Failure The effect's duration is 1 hour.","source":{"provider":"PAIZO","sourceId":"ksLCg62cLOojw3gN","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.plant-growth","name":"Plant Growth","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":["plant","vitality","wood"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Farming Lore or Survival","secondaryCasters":1},"description":"Area 1/2-mile-radius circle centered on you\n\nYou cause the plants within the area to be healthier and more fruitful. In addition to other benefits of healthy plants, this increases the crop yield for farms, depending on your success. If you cast it in the area of a , plant growth attempts to counteract the blight instead of producing its usual effect.\n\nCritical Success Double the crop yield in the area, or increase the area to a 1-mile radius.\n\nSuccess Increase the crop yield in the area by one-third.\n\nFailure The ritual has no effect.\n\nCritical Failure The flora in the area changes in an unanticipated way, determined by the GM but generally as contradictory to your true desires as possible (for instance, blighting crops when you would prefer to enrich them).","source":{"provider":"PAIZO","sourceId":"ZhJ8d9Uk4lwIx86b","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.precious-metals","name":"Precious Metals","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate","metal"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 metal shield or weapon, 1 suit of metal armor, or up to 1 Bulk of metal material (such as coins or metal-tipped ammunition)","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your deity blesses base metals to transform them into precious materials. The metal in the target transforms from its normal metal into cold iron, copper, gold, iron, silver, or steel. If the spell's rank is 8th or higher, add adamantine and dawnsilver to the options. If you transform an object into copper, gold, or silver, its Hardness is reduced to 1. Otherwise, its Hardness is increased to 10 if it was lower. An item transmuted in this way deals damage according to its new material. For example, a steel sword transmuted to cold iron would deal additional damage to a creature with a weakness to cold iron. It can have other effects of the new material at the GM's discretion.\n\nThis change is clearly magical and temporary, so the item's monetary value doesn't change; you couldn't transmute copper coins to gold and use them to purchase something.\n\nHeightened (+1) If you increase the Hardness of the object, the new Hardness is 2 higher.","source":{"provider":"PAIZO","sourceId":"APTMURAW1N0Wpk4w","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.procyal-philosophy","name":"Procyal Philosophy","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["auditory","concentrate","good","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The racoon-like visage of a sagacious procyal appears, dispensing helpful advice. The image appears floating next to the target. The image is just a floating magical manifestation and doesn't occupy any space. The procyal offers helpful suggestions, preparing to Aid the target as though the procyal had its own reaction. The procyal uses a bonus equal to your spell DC - 10 for its rolls to Aid.\n\nOn each of your turns, the procyal prepares to Aid its target again. You can use a free action, which has the concentrate trait, to redirect the procyal image to a different creature, changing the target of the spell. Otherwise, the procyal keeps aiding the same creature for the duration of the spell.","source":{"provider":"PAIZO","sourceId":"4cEDhvchskRvxSw6","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prophets-luck","name":"Prophet's Luck","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or a creature within range attempts a saving throw against an obvious threat.\nYou prophesize the result of the triggering saving throw as either a success (including a critical success) or a failure (including a critical failure). The target gains a +1 status bonus to the save if you predict success or a –1 status penalty if you predict failure. If you predict the result correctly, fortune favors you, and you gain a +1 status bonus to saving throws. If you predict incorrectly, fortune spurns the target, imparting a –1 status penalty to its saving throws.\nHeightened (6th) The save bonus or penalty increases to +2 or –2.\n\nHeightened (9th) The save bonus or penalty increases to +3 or –3.","source":{"provider":"PAIZO","sourceId":"n2CM3NeRuq5RSY19","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.protectors-sphere","name":"Protector's Sphere","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A protective aura emanates out from you, safeguarding you and your allies. You gain resistance 3 to all damage. Your allies also gain this resistance while in the area.\n\nHeightened (+1) The resistance increases by 1.","source":{"provider":"PAIZO","sourceId":"DH9Y3RQGWO0GzXGU","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pulse-of-civilization","name":"Pulse of Civilization","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","scrying"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"25 miles"},"area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You tap into the zeitgeist of any settlements in range. You learn the names of the settlements. On all Lore checks to Recall Knowledge about those settlements or to Gather Information in or about those settlements, you gain a +2 status bonus and use your level as your proficiency bonus even if you're untrained. When you Cast the Spell, you can immediately Recall Knowledge about one of the settlements using its Lore skill (such as Absalom Lore), which benefits from the bonus. If you cast pulse of civilization again, any previous casting ends.\n\nHeightened (5th) The range is 100 miles.\n\nHeightened (7th) The range is 500 miles and the bonus is +3","source":{"provider":"PAIZO","sourceId":"ivKnEtI1z4UqEKIA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.purifying-veil","name":"Purifying Veil","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","holy","manipulate","spirit","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 Large or smaller creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"vd71gprd4cz7vb2j","formula":"4d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"vd71gprd4cz7vb2j":"1d6"}},"counteraction":false,"ritual":null,"description":"Drawing on the purifying powers of water, you call forth a veil of fine water droplets suffused with holy energy. The veil surrounds the target. Everything on each side of the veil is from creatures on the opposite side, but the water doesn't impede attacks or movement across the veil. If the target moves through the veil, it takes 4d6 spirit damage with a basic Will save. If the target leaves the veil, the spell ends.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"3ySPK8qwNcuESwa0","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.radiant-beam","name":"Radiant Beam","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","good","holy","light","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":120}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"fcjtz4q0zrtvmtro","formula":"5d10","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"fcjtz4q0zrtvmtro":"1d10"},"areaFeet":0},"counteraction":true,"ritual":null,"description":"You fire a beam of blinding light from your outstretched hands. The beam deals 5d10 spirit damage. On a failed saving throw, a creature becomes for 1 round, or dazzled for 4 rounds on a critical failure.\n\nIf the light passes through an area of magical darkness or targets a creature affected by magical darkness, radiant beam attempts to counteract the darkness. If you need to determine whether the light passes through an area of darkness, draw a line between yourself and the target.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"5LGDygjRxURUOKGR","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.radiant-heart-of-devotion","name":"Radiant Heart of Devotion","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","light","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You speak a fervent prayer for the heavens to assist you and your righteous allies. Your heart begins to glow with a radiance that fills the area with bright light. The spell has the following effects on creatures in the area, based on the creature's alignment on the good-evil axis.\n\n- Good Creatures Good creatures in the emanation gain a +1 status bonus to attack rolls and their Strikes deal an additional 1d6 spirit damage.\n\n- Neutral Creatures Neutral creatures that begin their turn in the emanation must succeed at a Will save or be for 1 round.\n\n- Evil Creatures Evil creatures that begin their turn in the emanation must succeed at a Will save or be for 1 round.\n\nHeightened (+2) The additional spirit damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"yfCykJ6cs0uUL79b","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ranages-circle","name":"Ranage's Circle","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["auditory","concentrate","earth","linguistic","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Many stories tell of a clearing deep in the Mwangi jungle, surrounded by ancient cypress trees. At the center stands an ancient baobab tree growing around a large sphere of black basalt. Legends say that two spirit brothers, Ranage and Golokango, dwelled there long ago until Golokango's evil ways forced the virtuous Ranage to encase his brother in stone. Ranage then transformed himself into a tree to surround and protect the rock for all time. By telling this tale, you condemn an enemy to a stony fate similar to Golokango's and summon plants to surround them.\n\nWhen you Cast this Spell, every square adjacent to the target becomes difficult terrain from the sudden eruption of plant life for 1 minute. The target also attempts a Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target is Clumsy 1 as their feet are bound within stone. This condition lasts until they move from their current position.\n\nFailure The target is Clumsy 2 and as their legs are encased in rock. The clumsy condition lasts until they move from their current position, and they can from being immobilized with a check against your spell DC.\n\nCritical Failure The target is clumsy 2 and as nearly their entire body is covered in basalt. The clumsy condition lasts until they move from their current position, and they can Escape from being restrained with a successful check against your spell DC.","source":{"provider":"PAIZO","sourceId":"Pmhlv3fzPTuIhTrT","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rapid-retreat","name":"Rapid Retreat","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","teleportation","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":20},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You take damage from an attack or spell.\nYou know how to swiftly escape from harm. You instantly teleport out of danger into an unoccupied space within range, and you gain resistance to all damage against the triggering damage equal to your level. You can't Cast this Spell if there's no space to move into.","source":{"provider":"PAIZO","sourceId":"6sNjsNPipZvQ3BGe","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ravenous-portal","name":"Ravenous Portal","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 door no more than 10 feet tall and 5 feet wide","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You place a ward upon the door that triggers when a creature attempts to open, unlock, or destroy the door. When that happens, the door transforms into a that can't move and is hostile to all creatures. When Casting the Spell, you designate yourself and up to 10 other creatures of your choice; these creatures don't trigger the ward, and the mimic is helpful to them instead of hostile. No effect can move the mimic unless it's also capable of moving the entire door. Once the door transforms into a mimic, it attacks creatures in its reach for up to 1 minute, and then the spell ends. If the mimic is killed before that time, the spell ends and the door returns to its normal form.\n\nWhile turned into a mimic, the door can't be opened, unlocked, or bypassed-not even by the designated creatures. It's a creature, not a door, during that time. When the spell ends, the door returns to the state it was in before the ward was triggered.","source":{"provider":"PAIZO","sourceId":"ER1LOEgCLtmEKd05","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.read-omens","name":"Read Omens","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","prediction"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You peek into the future. Choose a particular goal or activity you plan to engage in within 1 week, or an event you expect might happen within 1 week. You learn a cryptic clue or piece of advice that could help with the chosen event, often in the form of a rhyme or omen.","source":{"provider":"PAIZO","sourceId":"pkcOby5prOausy1k","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rebounding-barrier","name":"Rebounding Barrier","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are hit by a physical Strike.\n\nYou swiftly raise a reflective barrier, reducing physical damage and rebounding it onto your attacker. You gain resistance 10 against one physical damage type the triggering attack deals. Your attacker takes 5 damage of the same type.\n\nHeightened (+1) The resistance increases by 2. Damage dealt to your attacker increases by 1.","source":{"provider":"PAIZO","sourceId":"5p8naLYjFcG13OkU","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rebuke-death","name":"Rebuke Death","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","healing","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"NONE"},"target":"1 living creature per action spent to Cast this Spell","area":{"shape":"EMANATION","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You snatch creatures from the jaws of death, restoring them without the straing of a typical close call. You can spend 1 to 3 actions Casting this Spell, and you can target a number of creatures equal to the actions spent. Each target regains 3d6 Hit Points. If the target had the condition, coming back from Dying due to this healing doesn't increase its condition.\n\nHeightened (+1) Increase the healing by 1d6.","source":{"provider":"PAIZO","sourceId":"4nHYSMHito1GUXlm","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.recall-past-life","name":"Recall Past Life","kind":"RITUAL","rank":4,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"3 days"},"cost":"100 gp in special wine and symbolic herbs"},"targeting":{"range":{"kind":"NONE"},"target":"the secondary caster who doesn't perform the Crafting check","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (master) or Religion (master)","secondaryChecks":"Crafting","secondaryCasters":2},"description":"You and the secondary casters spend 2 days drawing sigils on one another. At the end of the second day, the secondary caster responsible for the Crafting check carefully mixes the wine with the herbs and a small amount of saliva or blood from the target. The target then drinks the concoction, entering a state of metaphorical death and rebirth, their body becoming comatose for the final day of the ritual. During this time, you and the other secondary caster bathe the body in dirt, symbolizing a grave, and sprinkle the remainder of the wine around the body. If done properly, swaddled baby orchids grow around the area, enveloping the body in a bed of flowers.\n\nOn the final hour, the target returns to life, waking up temporarily possessed by an incarnation from one of their past lives. Though they retain the memories from their current life, their demeanor and personality are different for the remaining duration of the ritual, and they also remember vivid details from their past life. Unfortunately, it's impossible to choose a particular past self or to know whether a given former incarnation has good or bad intentions.\nCritical Success The target's personality reverts to a previous incarnation, determined by the GM. Normally they keep their abilities, but in rare cases, the GM might determine that the past incarnation has a different set of abilities based on their previous life. The lingering knowledge of the past incarnation is powerful and sticks with the target, allowing them to retrain one of their skills increases into a skill in which the past incarnation was particularly talented; the list of possible skills depends on the nature of the past incarnation and is determined by the GM.\n\nSuccess As critical success, except there's no lingering knowledge, and the target isn't able to retrain a skill increase.\n\nFailure Nothing happens, though the target's state is disturbing, and they wake up as well as likely disoriented.\n\nCritical Failure The sigils are drawn improperly, or the wine was tainted. The swaddled baby orchids that grow around the body scream at the moment when the target would've awakened. The target dies and their body is immediately possessed by a malevolent spirit that seeks to destroy their former allies. Use the statistics for a using Malevolent Possession on the target's body.","source":{"provider":"PAIZO","sourceId":"bqx1tJeOZq1Ufhcc","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.reflected-beauty","name":"Reflected Beauty","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"When you cast reflected beauty, choose a willing creature that's the same size as you and that you can see within 30 feet. The spell then disguises you with a realistic illusion, as if via heightened to 3rd rank, but includes tactile and olfactory sensation in addition to visual and voice. The appearance of the illusion that disguises you includes any changes to sex characteristics or other aspects needed to match the target creature's heart's desire, allowing you to interact with them as the person they could be. If you're ever more than 30 feet from the subject you're reflecting, reflected beauty immediately ends. You can Dismiss this spell.","source":{"provider":"PAIZO","sourceId":"ghIoycTH6gxxAw3w","book":"Pathfinder #205: Singer, Stalker, Skinsaw Man","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.reflective-scales","name":"Reflective Scales","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grow a set of colored, glowing scales or scaled armor that stores energy before releasing it in a final burst. When you cast this spell, choose acid, cold, fire, electricity, or poison damage. You gain resistance 5 against that type of damage. The scales' color depends on the damage type you chose, such as red or orange for fire damage.\n\nThe scales store up energy as they protect you. Keep track of how much damage the scales have prevented. As a 2-action activity that has the concentrate and manipulate traits, you can explode your scales outward in a , dealing 1d6 damage of the chosen type to all creatures in the area for every 10 damage the scales have prevented, to a maximum of 10d6 damage (after preventing 100 damage). Each creature in the area must attempt a basic Reflex save. Once you do so, the spell ends.\nHeightened (+2) The resistance increases by 5, and the maximum damage from the scale explosion increases by 5d6.","source":{"provider":"PAIZO","sourceId":"Mv5L4201uk8hnAtD","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.reinforced-rations","name":"Reinforced Rations","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"}},"targeting":{"range":{"kind":"NONE"},"target":"all food and drink in the area","area":{"shape":"EMANATION","feet":50}},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Cooking Lore (expert) or Crafting (expert)","secondaryCasters":0},"description":"An army marches on its stomach, and a city under siege is often cut off from its normal food supplies, so preserving comestibles is of utmost importance during a prolonged conflict. You enchant food and water in the area to not decay or spoil for the duration and grant better nourishment according to the success of the ritual. At the end of the duration, the food and water return to the state they were before the ritual.\nCritical Success A single meal of the affected food contains enough nourishment to sustain a typical human for 3 days.\n\nSuccess A single meal of the affected food contains enough nourishment to sustain a typical human for 1 day.\n\nFailure The ritual has no effect.\n\nCritical Failure The food and water in the area rots and spoils rapidly, releasing noxious fumes. Each living creature in the area becomes Sickened 2 and can't reduce the value of this condition for 24 hours.","source":{"provider":"PAIZO","sourceId":"2LsiiZZIZEKD23VQ","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.remember-the-lost","name":"Remember the Lost","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30,"text":"30-foot-radius emanation centered on you"}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You call upon the lost and forgotten, assailing your foes' minds with the memories of those who died with a grievance toward them. Enemies in the area take 6d6 mental damage (basic Will save) and are Frightened 1 on a critical failure.\n\nIf you know the names of anyone murdered or grievously wronged by an enemy in the area, you can chant those victims' names when you Cast the Spell to improve the clarity of the visions, increasing the damage to the corresponding enemy from 6d6 to (2*(@item.level - 1))d10[mental|shortLabel]; you can do so for multiple enemies if you know specific victims of each enemy. The visions are personal to each foe in the area, and you can't use this spell to discern a murderer by guessing a name. A creature that truly knows no one who died with any sort of grievance to that creature is immune to this effect.\nHeightened (+1) The damage increases by 2d6 (or 2d10 to an enemy when you name a specific victim).","source":{"provider":"PAIZO","sourceId":"nrW6lGV4xDMqLS3P","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.repel-metal","name":"Repel Metal","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","metal"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the creature targeted by the triggering Strike","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A Strike with a metallic weapon or projectile would hit you or an ally within range.\n\nYou call forth a repelling field. The target gains a +2 circumstance bonus to AC against the triggering attack. If the attack then misses, you direct the Strike back at the attacker, who compares the attack roll to their own AC. The target then becomes immune to this spell for 10 minutes.","source":{"provider":"PAIZO","sourceId":"pZBovpzdBNLQQQmE","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.replicate","name":"Replicate","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 willing or unconscious creature of 8th level or lower","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusory magical double that physically looks and behaves very similarly to the target. This double is limited to moving, Interacting, speaking short sentences, and other similar basic tasks. It is unable to cast spells, attack, or use any complex skills.\n\nThe illusory duplicate is your minion. You can issue new commands to the double as part of Sustaining the Spell. You can command the duplicate telepathically as long as the spell lasts, provided it's within 1 mile of you. You can switch between using your own senses and the duplicate's senses with a single action, which has the concentrate trait. The illusory duplicate has the same statistics as the original creature, except it doesn't have any of the original's item bonuses, and it has one quarter of the original's Hit Points. If the double's Hit Points are reduced to 0, the spell ends.\n\nHeightened (+1) The maximum level of the target increases by 2.","source":{"provider":"PAIZO","sourceId":"srEKUvym9kDVbEhD","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rest-eternal","name":"Rest Eternal","kind":"RITUAL","rank":4,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare oils to anoint the body worth a total value of the target's level (minimum 1) × 25 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"1 dead creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert)","secondaryChecks":"Occultism, Religion","secondaryCasters":2},"description":"You call upon gods, spirits, and stranger beings to bar a creature's spirit from ever returning. A spirit that doesn't wish to be so constrained can attempt a Will save to resist this ritual; on a critical success, it fools you into believing the ritual succeeded. This ritual has no effect on a target who is undead or whose soul is otherwise not in the afterlife.\nCritical Success You sequester the subject's spirit to the afterlife. Attempts to communicate with the dead creature, return it to life, turn it into an undead, or otherwise disturb its afterlife fail unless the effect's counteract rank is at least 2 higher than that of rest eternal or originates from an artifact or a deity. Successfully returning the creature to life ends the restrictions placed by rest eternal.\n\nSuccess As critical success, but effects to interact with the spirit fail unless the effect's counteract rank is higher than that of rest eternal or originates from an artifact or a deity.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual fails, and the spirits you appealed to are angered. All casters become Doomed 1 for 1 week.","source":{"provider":"PAIZO","sourceId":"MTNlvZ0A9xY5sOg1","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.retreat-among-the-rains","name":"Retreat Among the Rains","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["mental","water"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"at least 5 drops of water from a naturally occurring source (such as rainfall, rivers, or the seas) placed on the primary caster's face"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master) or Occultism (master)","secondaryChecks":"Cooking Lore, Survival","secondaryCasters":1},"description":"Ganhil developed this ritual to emulate the epiphanies and flowing mental states he experienced during 4718's Challenge of Sky and Heaven: intense focus, emotional acceptance, dilated perceptions, and growing awareness of elemental perfection.\n\nDuring the casting of this ritual, your thoughts enter a mindscape whose subjective flow of time is different, allowing you to perform retraining that would take a least a week of downtime. Your physical body still requires food or shelter during this time, so the secondary caster must nourish you with milk porridge or protect you from the elements with a raised parasol or similar item.\nCritical Success At the end of the ritual, you can retrain a class feature, feat, or skill.\n\nSuccess At the end of the ritual, you can retrain a feat or skill.\n\nFailure At the end of the ritual, you gain the condition.\n\nCritical Failure As failure, and you also suffer from starvation and thirst as if you hadn't eaten for a week, taking (10d4+7) damage that cannot be healed until you eat and drink.","source":{"provider":"PAIZO","sourceId":"D4Rxud1DBr52Dmdo","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.retributive-pain","name":"Retributive Pain","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate","mental","nonlethal"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature in range damages you.\n\nYou vengefully reflect your pain upon your tormentor. The target takes mental damage equal to half the triggering damage.","source":{"provider":"PAIZO","sourceId":"SSsUC7rZo0CwayPn","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rewrite-memory","name":"Rewrite Memory","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You alter the target's memories by erasing a memory, enhancing a memory's clarity, altering a memory, or adding a false memory. The target can attempt a Will save to resist the spell.\n\nCritical Success The target is unaffected and realizes you tried to alter its memory.\n\nSuccess The target is unaffected but thinks your spell was something harmless instead of rewrite memory, unless it identifies the spell.\n\nFailure During the first 5 minutes of the spell's duration, you can Sustain the spell to modify a memory once each round. When you do, you imagine up to 6 seconds of memory to modify, to a maximum of 5 continuous minutes of memory.\n\nAny memories you've altered remain changed as long as the spell is active. If the target moves out of range before the 5 minutes is up, you can't alter any further memories.\n\nHeightened (6th) You can Cast the Spell on a willing target to suppress all memory of a particular topic, detailed in 50 words or fewer. The effect is permanent, and it patches these omissions with an indistinct haze.","source":{"provider":"PAIZO","sourceId":"FhOaQDTSnsY7tiam","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rigid-form","name":"Rigid Form","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You utilize wood's rigidity to prevent harmful shapechanging effects. For the duration of this spell, whenever you're targeted by a harmful polymorph effect, you can use your reaction to attempt to counteract the effect.\n\nHeightened (6th) The duration increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"Ey4pKybxyPAxq0ew","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.roar-of-the-dragon","name":"Roar of the Dragon","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["auditory","cleric","concentrate","emotion","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel the might of dragons into your voice, letting out a roar that engenders respect in dragonkind but that instills fear in most other creatures. The impressive roar grants you a +2 circumstance bonus to Diplomacy checks for 10 minutes against dragons that were in the area at the time of casting.\n\nRoar of the dragon affects non-dragon creatures with deep ties to dragonkind (such as a barbarian with the draconic instinct, a sorcerer with the draconic bloodline, or a member of a culture that reveres dragons) as if they had the dragon trait. The GM decides if a creature is aligned enough with dragonkind to be affected in this way. All enemies within the area other than dragons must attempt a Will save; to these enemies, roar of the dragon is a fear effect.\nCritical Success The creature is unaffected.\n\nSuccess The creature is Frightened 1.\n\nFailure The creature is Frightened 2.\n\nCritical Failure The creature is Frightened 3 and for 1 round.","source":{"provider":"PAIZO","sourceId":"FSu6ZKxr3xdS75wq","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rope-trick","name":"Rope Trick","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","extradimensional","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 touched piece of rope from 5 to 30 feet long","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause the target rope to rise vertically into the air. Where it ends, an extradimensional space opens, connected to the top of the rope. This space can be reached only by climbing the rope.\n\nThe entrance to the space can't be seen, and it can be pinpointed only by the presence of the rope. The rope can't be removed or hidden, though it can be detached from the extradimensional space by pulling it with 16,000 pounds of weight, critically succeeding at an Athletics check against the spell's DC, or destroying the rope. The space holds up to eight Medium creatures and their gear. A Large creature counts as two Medium creatures, a Huge creature counts as four Medium creatures, and a Gargantuan creature fills the space on its own.\n\nIf the rope is detached or destroyed, or if a creature attempts to enter the space that would put it over its capacity, the space begins to unravel. It disappears in [[/r 1d4 #rounds]]{1d4 rounds}, depositing the creatures within safely on the ground below.","source":{"provider":"PAIZO","sourceId":"GzdgM0m7wXKuFSho","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rune-of-observation","name":"Rune of Observation","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You inscribe an invisible eye-shaped rune in the air, creating a sensor as . When created, this eye must be in your line of sight.\n\nEach time the spell's duration ends, you can spend 1 Focus Point as a free action to extend the duration for another hour, though as normal, it ends immediately during your next daily preparations.","source":{"provider":"PAIZO","sourceId":"4LSf04FFvDgMyDk6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.runic-impression","name":"Runic Impression","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","magus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"you or one weapon you're wielding","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your unarmed attacks or weapon gain the benefits of a weapon rune you choose when you cast this spell: , , , , , , or . If you cast runic impression on a weapon, this spell ends if you cease holding the weapon, with the exception of throwing a returning weapon. If this spell would give a weapon more property runes than its normal maximum, one of the existing property runes (you choose) is suppressed until the spell ends. For unarmed attacks, if this spell would give you more property runes than you could have from handwraps of mighty blows, one of the existing property runes is similarly suppressed.\nHeightened (8th) Add keen to the list of runes you can choose as well as the greater types of Corrosive, Flaming, Frost, Shock, and Thundering.","source":{"provider":"PAIZO","sourceId":"oOaEfsdVpgTXRhrY","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rust-cloud","name":"Rust Cloud","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"kmgVwzdXySlwrW7I","formula":"5d10","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"kmgVwzdXySlwrW7I":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Red-blown flecks of rust jitter in the air, forming a cloud of agitated particles. All creatures within the cloud become , and all creatures outside the cloud become concealed to creatures within it. The cloud deals 5d10 slashing damage to any creature that starts its turn in the area, with a basic Fortitude save.\n\nMetal that rusts off of a creature adds to the cloud. When a metal creature takes damage from the cloud, the cloud's area increases by 5 feet (to a maximum of a ), and the creature starts to rust, taking (floor(@item.level/2)-1)d4[persistent,slashing] damage. You can Dismiss the cloud.\n\nHeightened (+2) The cloud's slashing damage increases by 1d10 and the persistent damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"yy2K51kK3a60rRIe","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.rusting-grasp","name":"Rusting Grasp","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 metal creature, 1 non-magical metal hazard, or 1 non-magical metal item of up to 1 Bulk","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause the target to rapidly rust. This magical rust can affect nonferrous materials, but the target must be all or mostly metal. Skymetals such as adamantine and orichalcum are immune to this rust, and the GM might determine other precious materials are similarly resilient. Ultimately, the GM decides if an object or creature can be targeted with this spell.\n\nAll damage from this spell ignores Hardness. If the spell causes persistent damage from rust, a creature can attempt to scrape off the rust to assist the target in recovering from the persistent damage (reducing the DC of the flat check to end persistent damage to 10 and granting an immediate flat check). The effect of the spell depends on its target.\n\n- Creature or Hazard A creature or hazard must be made of all or mostly metal to be affected (this includes many mechanical traps). The grasp deals 8d6 damage (basic Fortitude save), plus 2d6[persistent] on a failed save. Touching a hazard to affect it with this spell might trigger the hazard, as determined by the GM.\n\n-\nItem The rust deals [[/r {2d6}]]{2d6 damage}, subject to a basic Reflex save by the creature wearing or holding the item; if the item is unattended, it automatically gets a critical failure. On a failed save, the item also takes 1d6[persistent]. For an attended item, this persistent damage occurs at the end of the attending creature's turns; if the item was unattended when you Cast the Spell, the damage happens at the end of your turns.\n\nWhen targeting armor someone is wearing, its Bulk is 1 higher than the listed value, since carrying armor is more cumbersome than wearing it. Thin iron or steel items, such as weapons, have 20 HP and a Broken Threshold of 10, and thicker iron or steel items, such as most suits of armor, have 36 HP and a Broken Threshold of 18.\n\nHeightened (+1) Increase the initial damage to creatures or hazards by 2d6, and increase the maximum Bulk of an item you can target by 1.","source":{"provider":"PAIZO","sourceId":"0fYE64odlKqISzft","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sacred-nimbus","name":"Sacred Nimbus","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","holy","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"SQUARE","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"VZH6f22B2X2tWam3","formula":"5d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"VZH6f22B2X2tWam3":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You summon a small, fluffy white nimbus cloud that floats 10 feet above the ground and rains down pleasantly warm sanctified water. The rain deals 5d6 spirit damage to fiends, undead, and creatures that have a weakness to spirit damage in the area at the end of your turn. When you Sustain the spell, you can move the cloud at a fly speed of 15 feet to anywhere in the spell's range. The water dissipates as it makes contact with any creatures or surfaces, leaving only a bit of humidity in its place.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"GabRQPc9qD86jDGI","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.safeguard-secret","name":"Safeguard Secret","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you and any number of willing allies","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ensure a secret remains safe from prying spies. Choose one piece of information that at least some of the targets know, such as \"the location of the stolen treasure\" or \"the password to enter the guild house.\" The spell grants those who know the piece of knowledge you have chosen a +4 status bonus to skill checks (typically Deception checks) to conceal this knowledge, and to saving throws against spells that specifically attempt to obtain this knowledge from them, and to effects that would force them to reveal it.\n\nIf you Cast this Spell again, any previous safeguard secret you had cast ends.","source":{"provider":"PAIZO","sourceId":"OsrtOeG0TvDNnEFH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sages-curse","name":"Sage's Curse","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate","mental","misfortune"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You afflict the target with a curse that fills its mind with distracting and hyperspecialized minutiae, causing it to second-guess even simple facts. The target must attempt a Will saving throw.\n\nCritical Success The target is unaffected.\n\nSuccess For 10 minutes, the target must roll twice and use the worse result whenever attempting an Arcana, Lore, Occultism, or Society check. If the target succeeds at a check to Recall Knowledge, it gains one piece of true knowledge and one piece of erroneous knowledge, but it has no way of knowing which is which (this has no effect if the target critically succeeds at a check to Recall Knowledge).\n\nFailure As success, but the effect is permanent.\n\nCritical Failure As failure, and the target treats the outcomes of all checks to Recall Knowledge as one degree of success worse than the result the target rolled (a critical success becomes a success, a success becomes a failure, and a failure becomes a critical failure).","source":{"provider":"PAIZO","sourceId":"APDrC83QljsyHenB","book":"Pathfinder Abomination Vaults Hardcover Compilation","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sanguine-mist","name":"Sanguine Mist","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","death","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You unleash a cloud of foul, blood-sucking fog that drains the vitality from the living to bolster your own. Each living creature in the area when you Cast the Spell, aside from you, takes 6d6 void damage with a basic Fortitude save. Creatures in the area are , and all creatures outside the cloud become concealed to creatures within it.\n\nThe first time each round you Sustain this Spell on subsequent turns, living creatures in the area take an additional (@item.rank -2)d6[void] damage with another basic Fortitude save. You also gain temporary Hit Points equal to half the damage a single creature took when you Sustained the spell this turn; calculate these temporary Hit Points using the creature that took the most damage. You lose any remaining temporary Hit Points after 1 minute.\nHeightened (+1) The initial damage increases by 2d6 and the secondary damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"5zeSxzDxMSr0wgSF","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.seal-fate","name":"Seal Fate","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","curse","death","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You utter a curse that a creature will meet a certain end—a death by freezing, stabbing, or another means you devise. Choose one type of damage from the following list: acid, bludgeoning, cold, electricity, fire, piercing, slashing, sonic, or void. The effect is based on the target's Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target gains weakness 2 to the chosen damage type until the end of your next turn.\n\nFailure As success, but the duration is 1 minute. If the creature is reduced to 0 Hit Points by the chosen damage and its level is 7 or less, it dies.\n\nCritical Failure As failure, but the duration is unlimited.\nHeightened (+2) The weakness increases by 1, and the maximum level of creature that can be automatically killed increases by 4.","source":{"provider":"PAIZO","sourceId":"gfKhtVsXF3HKSdmY","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-double","name":"Shadow Double","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["illusion"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"a small item of personal significance to the creature to be duplicated (such as an item of clothing they wear everyday or a memento of a romantic tryst), plus rare oils, minerals, and pigments with a total value of 300 gp"},"targeting":{"range":{"kind":"NONE"},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (master, the check has the secret trait)","secondaryChecks":"Arcana, Nature, Occultism, Religion, or Society (whichever is required to Recall Knowledge about the creature being duplicated); Crafting; Deception","secondaryCasters":3},"description":"You create an illusory duplicate of the target creature by drawing shadowy material from the Netherworld and sculpting it into a semi-solid form. The shadow double is a 4th-level creature with no special abilities. If it needs to attempt a roll or use a DC, use the moderate number for a monster, except as noted below. It doesn't have any specific memories from the target, but it can use information about the creature gained from any of the casters to Impersonate the target. It looks exactly like the target and has a Deception modifier to Impersonate that creature equal to the modifier of the secondary spellcaster who rolled the Deception check, with a +4 status bonus. Though it doesn't have any of the original's special abilities, like a dragon's breath, illusions allow it to appear to use those abilities; they just never seem to have an effect. For instance, against a double's dragon's breath, all creatures in the area seem to critically succeed at their saving throws and take no damage. Creatures can attempt to disbelieve the illusion by attempting a Perception check against the Deception DC of the secondary spellcaster who rolled the Deception check.\nCritical Success You create the shadow double. It has the minion trait and is under your absolute control. You gain a direct mental link with the shadow double and can spend an action to command the shadow double via this link, even at a distance.\n\nSuccess As a critical success, but there is no special link between you and the shadow double. You must spend an action to command it verbally or by some other means.\n\nFailure The ritual fails and has no effect.\n\nCritical Failure The shadow double is created, but it isn't your minion and is hostile to all the casters. It does everything it can to destroy them, but if it can't immediately slay them, the shadow double tries to escape and plots their demise.","source":{"provider":"PAIZO","sourceId":"h5UqEdeqK8iTcU0J","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shaken-confidence","name":"Shaken Confidence","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","emotion","focus","mental","misfortune"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"An enemy that critically failed an attack roll, Perception check, or skill check","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An enemy within 30 feet of you critically fails an attack roll, Perception check, or skill check.\n\nYou mock the target for all its failings, twisting its self-confidence into doubt. The enemy attempts a Will saving throw.\n\nSuccess The target is unaffected.\n\nFailure The target is briefly shaken and unsure of its abilities. It must roll twice and take the worse result on the next roll of the same type as the critical failure that triggered the spell (such as the target's next Acrobatics check if the spell's trigger was a critical failure on an Acrobatics check). If the target doesn't attempt any qualifying checks, the spell ends at the end of the target's next turn.","source":{"provider":"PAIZO","sourceId":"9j35xXKVVtHCh1Pe","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shape-stone","name":"Shape Stone","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"cube of stone 10 feet across or smaller","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shape the stone into a rough shape of your choice. The shaping process is too crude to produce intricate parts, fine details, moving pieces, or the like. Any creatures standing atop the stone when you reshape it must each attempt a Reflex save or Acrobatics check.\n\nSuccess The creature is unaffected.\n\nFailure The creature falls atop the stone.\n\nCritical Failure The creature falls off the stone (if applicable) and lands Prone.","source":{"provider":"PAIZO","sourceId":"McnPlLFvKtQVXNcG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shared-nightmare","name":"Shared Nightmare","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","emotion","focus","incapacitation","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Merging minds with the target, you swap distressing visions. One of you will become , based on the target's Will save.\n\nCritical Success You are Confused for 1 round.\n\nSuccess At the start of your next turn, you spend your first action with the Confused condition, then act normally.\n\nFailure The target spends the first action of each of its turns Confused. The duration is 1 minute.\n\nCritical Failure The target is Confused. The duration is 1 minute.","source":{"provider":"PAIZO","sourceId":"skvgOWNTitLehL0b","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shielding-formation","name":"Shielding Formation","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","force","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure magical shields of force to protect your allies around you. You and each ally who ends their turn within the emanation gain a +1 circumstance bonus to AC until they leave the emanation or the spell ends, whichever comes first. If an ally takes physical damage or damage from a spell or magical effect while being granted this bonus, they can choose to end the bonus for themselves as a free action to gain resistance 10 to all damage against the triggering damage. If they do, they become temporarily immune to the effects of shielding formation for 10 minutes. You can do the same by spending your reaction; if you do, you can't cast shielding formation again for 10 minutes, though you can continue Sustaining the benefits for others.","source":{"provider":"PAIZO","sourceId":"6QEWTuCKRQQTyoeS","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shifting-form","name":"Shifting Form","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","manipulate","morph","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You change your body to better suit the moment. You gain one of the following abilities of your choice. You can Dismiss this spell.\n\n- You gain a 20-foot status bonus to your Speed.\n\n- You gain a climb or swim Speed equal to half your Speed.\n\n- You gain darkvision.\n\n- You gain a pair of claws. These are agile finesse unarmed attacks that deal 1d8 slashing damage.\n\n- You gain scent 60 feet (imprecise).","source":{"provider":"PAIZO","sourceId":"SDkIFrrO1PsE02Kd","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.show-the-path","name":"Show the Path","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","fortune","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant the target insight on things to come, guiding them toward a fate they find most fitting and encouraging them to continue this journey. The creature rolls a d20 at the start of each of its turns. The creature can use the result of the roll instead of rolling for any check before the start of their next turn. If the creature does substitute the roll in this way, they gain a +1 status bonus to whatever check they substitute on the following turn. Repeated substitutions increase the status bonus by 1, up to a total of +2. If the creature begins their turn without having substituted a roll in the previous round, the spell ends.\nHeightened (7th) The status bonus can increase up to a total of +3.\n\nHeightened (10th) The status bonus can increase up to a total of +4.","source":{"provider":"PAIZO","sourceId":"jLc8tHSNeXm0RvMQ","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shroud-of-the-mantis","name":"Shroud of the Mantis","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","illusion","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrap yourself in a crimson cloak that renders you , with the same restrictions as a 2nd-rank spell.\nHeightened (6th) The duration increases to 10 minutes.\n\nHeightened (8th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"VVigI4uNdWr1XZgG","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sliding-blocks","name":"Sliding Blocks","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure up to six 5-foot stone cubes you can gently move with a gesture. Each cube appears in any space within range, and they're capable of levitating. If you conjure a cube in an occupied space or in a space that can't accommodate it, it fails to appear. Each 5-foot cube can be Climbed with a successful athletics check and has AC 10, Hardness 10, and 40 Hit Points. If any of the cubes is ever farther away from you than the range of this spell, it immediately crumbles into dust.\n\nEach time you Sustain this spell, you can move up to two of the conjured cubes up to 10 feet each in any direction, including vertically. You can choose different cubes to move each time you Sustain.\n\nHeightened (+2) The cubes have 10 additional Hit Points, and you can move the chosen cubes an additional 5 feet each time you Sustain this Spell.","source":{"provider":"PAIZO","sourceId":"avEutOjF2ox947fp","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.snake-fangs","name":"Snake Fangs","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","morph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your jaw unhinges as your teeth extend into wicked fangs. For the spell's duration, you gain a fangs unarmed attack. They're a finesse, grapple, unarmed attack that deals 1d8 piercing damage and an extra 2d10 poison damage. If you have a creature at least one size smaller than you with your fangs, you can use the ability that deals 4d6[bludgeoning] damage and has a Rupture value of 17. A swallowed creature is transported to an extraplanar space that resembles the inside of a snake's stomach, so when it gets free, it appears in a space adjacent to you. If you're killed or the spell ends, the swallowed creature is immediately freed.\n\nHeightened (+3) The extra poison damage of your fangs unarmed attack increases by 1d10, the damage dealt by the Swallow Whole ability increases by 6d6, and the Rupture value increases by 9.","source":{"provider":"PAIZO","sourceId":"wLWMswY7aBHEFTRb","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.soft-landing","name":"Soft Landing","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a magical field that buoys any creature or object falling into the area, providing a harmless landing from any height. As you generally fall 1,500 feet per round, you can cast this spell while you are falling to ensure a safe landing, provided you can see your landing point and it's within range.","source":{"provider":"PAIZO","sourceId":"TLmkJ8ga8s057HBp","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.solid-fog","name":"Solid Fog","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a bank of fog so thick it impedes movement as well as sight. This functions as , except that the area is also difficult terrain. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"piMJO6aYeDJbrhEo","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.songbirds-call","name":"Songbird's Call","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","bard","composition","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"zaWfV7AcltDYyyRz","formula":"1d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"zaWfV7AcltDYyyRz":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Your voice calls a storm of songbirds that whirl around you and peck at your enemies. All creatures within the area of whirling birds become , and all creatures outside the area become concealed to creatures within it. A creature other than you that enters or ends its turn in the area takes 1d6 piercing damage as the birds peck at it.\n\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"CzMCiFbgLj1irnP4","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.soothing-spring","name":"Soothing Spring","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality","water"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"10d8","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d8"}},"counteraction":false,"ritual":null,"description":"Steam wisps into the air as a stone-lined pool appears in the ground and fills with hot water that bubbles up from the earth. The water is comfortably hot and smells mildly sulfurous in a not-unpleasant way. You are able to draw out the full energizing potential of the mineral-rich water. Any creature that spends the full hour soaking in the hot spring or basking in the mud from the bottom of the pit regains 10d8 Hit Points and feels refreshed, losing the fatigued condition. As normal for effects that remove fatigue, this doesn't remove any underlying source of fatigue, such as lack of sleep, causing the condition to return if the underlying source isn't addressed.\n\nThe pool is 20 feet on each side, and it's 5 feet deep. It can contain 16 Medium or smaller creatures at a time. A Large creature counts as eight Medium creatures and a Huge creature fills the entire pool. This pool has the structure trait and the same restrictions as magic items that create structures.\n\nHeightened (+1) The healing increases by 2d8.","source":{"provider":"PAIZO","sourceId":"fH08MI4KP0KH2EQ9","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spell-immunity","name":"Spell Immunity","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You ward a creature against the effects of a single spell. Choose a spell and name it aloud as part of the verbal component. Spell immunity attempts to counteract that spell whenever spell immunity's target is the target of the named spell or in that spell's area. Successfully counteracting a spell that targets an area or multiple targets with spell immunity negates the effects only for the target affected by spell immunity.","source":{"provider":"PAIZO","sourceId":"tgIhRUFtgDSELpJE","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spike-stones","name":"Spike Stones","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Long, sharp spikes of solid rock thrust up from the ground in the area. The area becomes difficult terrain and hazardous terrain. A creature that moves on the ground through the area takes 3 piercing damage for every square of that area it moves into.\n\nHeightened (+1) Increase the damage by 1.","source":{"provider":"PAIZO","sourceId":"3xD8DYrr8YDVYGg7","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spiral-of-horrors","name":"Spiral of Horrors","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","concentrate","emotion","fear","focus","manipulate","mental","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Shades and spirits howl and whirl around you in a display that strikes fear into the hearts of all who witness it. Enemies in the area are Frightened 1 and can't reduce their frightened value below 1 for the spell's duration.","source":{"provider":"PAIZO","sourceId":"KPGGkyBFbKse7KpK","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spiritual-anamnesis","name":"Spiritual Anamnesis","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Memories of a past life that seem incredibly real (and may even be) overwhelm the target's mind. This is especially disorienting for undead and creatures that have lived a previous life (such as celestials, fiends, monitors, and many other extraplanar creatures); if such creatures roll a critical success on their save, they get a success instead, and if they roll a failure, they get a critical failure instead.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Slowed 1 for 1 round.\n\nFailure The target is Slowed 1 for 1 minute and babbles about the visions, possibly providing information about what they saw.\n\nCritical Failure As failure, but the target is also Stunned 3.","source":{"provider":"PAIZO","sourceId":"Jli9WBjQZ2MmKJ8y","book":"Pathfinder #147: Tomorrow Must Burn","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spiritual-attunement","name":"Spiritual Attunement","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You attune yourself to a spiritual plane of the Outer Sphere, connecting your spirit without fully transporting to it. Your Strikes and spells gain the alignment traits of the plane you chose, which deals additional damage to creatures with a weakness to either of those alignment traits. Furthermore, the plane protects you from energy of the alignments that oppose the plane. You gain resistance 5 to damage of the alignments that oppose those of your chosen plane. For example, if you chose Heaven, your Strikes would gain the good and lawful traits, and you would gain resistance to chaotic and evil. If you choose the Boneyard, the resistance is to vitality and void damage instead.\n\nHeightened (+2) The resistance increases by 5.\n\nThe nine main planes of the Outer Sphere are the homes of many deities, celestials, monitors, and fiends. Their names, along with their alignments, are: Heaven (LG), Nirvana (NG), Elysium (CG), Axis (LN), the Boneyard (N), the Maelstrom (CN), Hell (LE), Abaddon (NE), and the Abyss (CE).","source":{"provider":"PAIZO","sourceId":"GjmMFEJcDd6MDG2P","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spiritual-renewal","name":"Spiritual Renewal","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"4 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw upon the restorative power of the spirits around you. The target gains fast healing 8.\nHeightened (+1) The fast healing increases by 2.","source":{"provider":"PAIZO","sourceId":"tBC1QmB33KWIuBFX","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stasis","name":"Stasis","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","incapacitation","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature or up to 1 Bulk of objects","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The flow of time congeals around an object or creature, holding it in place. The target must attempt a Will save (an unattended object automatically critically fails its save).\nCritical Success The target is unaffected.\n\nSuccess The target is Stunned 1 as time thickens around it.\n\nFailure Time ceases to pass for the target for 1 round. It is invulnerable to all damage, it can't be targeted or affected by anything, and no rounds elapse for any timed durations, conditions, afflictions, and other effects it has. While in stasis, the target can't be moved, and it remains fixed in place, defying gravity if need be.\n\nCritical Failure As failure, but the target is held in stasis for 3 rounds. At the end of each of its turns, it can attempt a Will save to reduce the remaining duration by 1 round or end it entirely on a critical success.","source":{"provider":"PAIZO","sourceId":"cOwSsSXRsBaXUvlr","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.steal-voice","name":"Steal Voice","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","curse","incapacitation","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You steal a creature's voice, rendering them mute. The effect is determined by the target's Fortitude save. The target then becomes temporarily immune for 1 minute. A creature that has no voice or can't speak is immune to this spell.\n\nCritical Success The target is unaffected.\n\nSuccess The target becomes voiceless until the end of its next turn. A voiceless creature can't speak, create vocal sounds, or take auditory actions (including supplying verbal or command components). As long as the target is voiceless, whenever you speak, you can choose to have your voice sound like either your voice or the target's voice.\n\nFailure As success, but the duration is 1 minute.\n\nCritical Failure As success, but the duration is permanent.","source":{"provider":"PAIZO","sourceId":"5LrQIlimsPXK2xAG","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stifling-stillness","name":"Stifling Stillness","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"zqA3mumEYuVNchMC","formula":"3d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"zqA3mumEYuVNchMC":"3d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You make all air in the target area unnaturally still and unyielding, creating a shimmering haze. The stagnant, heavy air becomes an area of difficult terrain. Creatures in the area that breathe air and aren't holding their breath must spend a single action on their turn straining to breathe the stagnant air; once they do, they still mostly breathe their own exhaled air, taking 3d6 poison damage (basic Fortitude save) and becoming .\n\nHeightened (+2) The damage increases by 3d6.","source":{"provider":"PAIZO","sourceId":"bAxjHBi37CVwInfU","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.stonesense","name":"Stonesense","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain tremorsense as an imprecise sense to a range of 100 feet, but you can only sense vibrations through natural stone (not masonry, adobe, or any other manufactured edifice).","source":{"provider":"PAIZO","sourceId":"UVLiBXLLAoWhUU4R","book":"Pathfinder #194: Cult of the Cave Worm","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stormwind-flight","name":"Stormwind Flight","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["air","concentrate","druid","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Powerful winds carry you smoothly through the air, giving you a fly Speed equal to your Speed. When this spell's duration would end, if you're still flying, you float to the ground, as .\n\nHeightened (6th) When you fly using stormwind flight, you ignore difficult terrain from wind.","source":{"provider":"PAIZO","sourceId":"gSFg9zKwgcNZLMEs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.suggestion","name":"Suggestion","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","incapacitation","linguistic","manipulate","mental","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your honeyed words are difficult for creatures to resist. You suggest a course of action to the target, which must be phrased in such a way as to seem like a logical course of action to the target and can't be self-destructive or obviously against the target's self-interest. The target must attempt a Will save.\n\nCritical Success The target is unaffected and knows you tried to control it.\n\nSuccess The target is unaffected.\n\nFailure The target immediately follows your suggestion. The spell has a duration of 1 minute, or until the target has completed a finite suggestion or the suggestion becomes self-destructive or has other obvious negative effects.\n\nCritical Failure As failure, but the base duration is 1 hour.\n\nHeightened (8th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"qwlh6aDgi86U3Q7H","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.swarm-form","name":"Swarm Form","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You discorporate into a swarm of Tiny creatures. While in swarm form, you are the same size, you have the swarm trait and you gain resistance 5 to slashing and piercing damage and weakness 5 to area and splash damage. You can fit into spaces only a few inches wide, moving your constituent creatures through the gap, and you can share a space with another creature. You don't gain the swarm mind ability, so you are still affected normally by mental effects. As a swarm, you can't speak, cast spells, use manipulate actions requiring your hands, activate your magic items, or make any of your Strikes with your normal body. While in swarm form, you can crawl all over any creature that shares your space as a single action. That creature must attempt a Fortitude save against your spell DC or become Sickened 1 (Sickened 2 on a critical failure). You can Dismiss the Spell.\nHeightened (+2) Your resistances and weaknesses each increase by 5.","source":{"provider":"PAIZO","sourceId":"Pd2M1XY8EXrSfWgJ","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.swarming-wasp-stings","name":"Swarming Wasp Stings","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"10-foot burst","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"1d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You manifest a swarm of disembodied wasp stingers that stab creatures in the area, possibly poisoning them. Creatures in the affected area take 1d6[piercing] damage. Each creature that takes piercing damage must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 2d6[poison] damage.\n\nFailure The target is afflicted with Swarming Wasp Venom at stage 1.\n\nCritical Failure The target is afflicted with swarming wasp venom at stage 2.\n\nSwarming Wasp Venom (poison)\n\nLevel 7\n\nMaximum Duration 6 rounds\n\nStage 1 2d6[poison] damage and Clumsy 1 (1 round)\n\nStage 2 3d6[poison] damage and Clumsy 2 (1 round)","source":{"provider":"PAIZO","sourceId":"LVwmAH5NGvTuuQSU","book":"Pathfinder #160: Assault on Hunting Lodge Seven","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.take-its-course","name":"Take its Course","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"When someone has overindulged, you can hasten them past the worst of their affliction or intensify their misery. This spell attempts to progress a disease affliction, a poison affliction, or persistent poison damage affecting the target. If the target is affected by more than one of these, you can choose from among those you are aware of; otherwise the GM chooses randomly. An unwilling target can attempt a Will save to negate take its course.\n\nThe effect of this spell depends on whether you're attempting to end an affliction or persistent poison damage, and whether you are attempting to help or hinder the target's recovery.\n\n- Affliction The target immediately attempts its next saving throw against the affliction. You can grant the creature your choice of a +2 status bonus or a -2 status penalty to its saving throw against the affliction.\n\n- Persistent Poison You can cause the target take the persistent poison damage immediately when you Cast this Spell (in addition to taking it at the end of its next turn). Whether or not you do so, the target attempts an additional flat check against the persistent poison damage. You can set the DC of that flat check to 5 or 20 instead of the normal DC.\n\nHeightened (7th) You can attempt to progress any number of the target's eligible afflictions and persistent poison damage.","source":{"provider":"PAIZO","sourceId":"ZeHeNQ5BNq6m5F1j","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.talking-corpse","name":"Talking Corpse","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 corpse","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant the target corpse a semblance of life, which it uses to speak the answers to three questions posed to it. This spell calls on the physical body's latent memories rather than summoning back the deceased's spirit, so the corpse must be mostly intact for the spell to function. The more damage the corpse has taken, the more inaccurate or patchwork its answers are, and it must have a throat and mouth to speak at all. If anyone has previously cast this spell on the corpse in the last week, the spell automatically fails. The corpse can attempt a Will save to resist answering the questions using the statistics of the original creature at its time of death, with the following effects.\n\nCritical Success The target can lie or refuse to answer your questions, and the target's spirit haunts you for 24 hours, bothering you and causing you to be unable to gain any rest for that time.\n\nSuccess The target can provide false information or refuse to answer your questions.\n\nFailure The target must answer truthfully, but its answers can be brief, cryptic, and repetitive. It can still mislead you or attempt to stall so that the spell's duration runs out before you can ask all your questions.\n\nCritical Failure As failure, but the target's answers are more direct and less repetitive, though still cryptic. It takes a -2 status penalty to Deception checks to deceive or mislead you.","source":{"provider":"PAIZO","sourceId":"FM3SmEW8N1FCRjqt","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.telepathy","name":"Telepathy","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","linguistic","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can communicate telepathically with creatures within 30 feet. Once you establish a connection by communicating with a creature, the communication is two-way. You can communicate only with creatures that share a language with you.\n\nHeightened (6th) You can communicate telepathically with creatures using shared mental imagery even if you don't share a language; telepathy loses the linguistic trait.","source":{"provider":"PAIZO","sourceId":"HqTI6wRrck1YXp3F","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tempt-fate","name":"Tempt Fate","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","fortune","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or an ally within range attempts a saving throw.\n\nYou twist the forces of fate to make a moment dire or uneventful, with no in-between. The target gains a +1 status bonus to the triggering saving throw. If the saving throw's result is a success, it becomes a critical success. If it's a failure, it becomes a critical failure, and the critical failure can't be reduced by abilities that usually reduce critical failure.\n\nIf the triggering ability did not have both a critical success and critical failure condition, tempt fate fails, but you don't expend the Focus Point for Casting this Spell.\n\nHeightened (8th) The bonus on the saving throw is +2.","source":{"provider":"PAIZO","sourceId":"GqvKSxzN7A7kuFk4","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tireless-worker","name":"Tireless Worker","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","healing","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You suppress your choice of one of the following conditions that's affecting the target: , , , or . The duration of the condition doesn't elapse while it is suppressed, so if you don't remove the effect that caused the condition, the condition returns after the spell's duration expires.","source":{"provider":"PAIZO","sourceId":"gzvRDpM6EvcfYHeu","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tomorrows-dawn","name":"Tomorrow's Dawn","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","light","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The golden light of a new dawn and the promise of life beyond death radiates from your body. You radiate bright light in a 20-foot radius (and dim light for the next 20 feet) and gain mental resistance 5. Any nindoru fiend or undead that begins its turn adjacent to you must attempt a Will save with the following results.\n\nCritical Success The creature is unaffected and immune to this spell's effects for the remainder of the spell's duration.\n\nSuccess The creature is Sickened 1 until the end of its turn.\n\nFailure The creature is sickened 1. In addition, it becomes Slowed 1 until the end of its next turn.\n\nCritical Failure As failure, but Sickened 2 and the creature remains slowed 1 for the rest of the spell's duration.\nHeightened (6th) You gain mental resistance 10.\n\nHeightened (8th) You gain mental resistance 15.","source":{"provider":"PAIZO","sourceId":"a0MfDnUa33oWM74s","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tortoise-and-the-hare","name":"Tortoise and the Hare","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 foe, and either yourself or 1 ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You prove that slow and steady doesn't always win the race by turning a foe into a proverbial tortoise and yourself or an ally into a hare, siphoning some of the foe's speed and granting it to the other target. The effects depend on the foe's Fortitude save.\n\nCritical Success The targets are unaffected.\n\nSuccess The foe is Slowed 1 for 1 round, and the other target is unaffected.\n\nFailure The foe is slowed 1 for 3 rounds and the other target is for 1 round. It can use the extra action to Step, Stride, or Strike.\n\nCritical Failure The foe is slowed 1 for 3 minutes and the other target is quickened for 1 minute. It can use the extra action to Step, Stride, or Strike.","source":{"provider":"PAIZO","sourceId":"1NLMPmyCB2MBoCuR","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.touch-of-the-moon","name":"Touch of the Moon","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","focus","light","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"When you touch the target, a symbol of the moon appears on its forehead, glowing with soft moonlight. The target glows with dim light in a 20-foot radius. It also gets a benefit based on a phase of the moon, starting with the new moon and changing to the next phase at the end of each of its turns.\n\n- New Moon The target receives no benefit.\n\n- Waxing Moon The target gains a +1 status bonus to attack rolls and a +4 status bonus to damage rolls.\n\n- Full Moon The target gains a +1 status bonus to attack rolls, AC, and saves, and a +4 status bonus to damage.\n\n- Waning Moon The target gains a +1 status bonus to AC and saving throws. After this phase, return to the new moon.","source":{"provider":"PAIZO","sourceId":"oXCwHBeDja4e0Mx0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.transcribe-moment","name":"Transcribe Moment","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You instantly create a small, permanent scroll that contains a magically precise written description of your current surroundings in every direction. Any creature who spends 1 minute to read the scroll-written in a language of your choice that you know-immediately sees and experiences your surroundings during the moment that you recorded (including whatever events transpired that round) exactly as you experienced it. This depiction records only what you can sense yourself. For example, if you can't see invisible creatures, the depiction doesn't reveal them even to a reader who could normally see them; a reader can't use their Perception to notice details you missed, but they can attempt a check to Recall Knowledge based on what they just experienced if they have knowledge that you lack. You can have multiple scrolls from transcribe moment in existence at the same time, up to a number equal to your Intelligence modifier. If you Cast the Spell again while already at the maximum number of scrolls, choose one of the current scrolls to lose its magic, then create the new one.","source":{"provider":"PAIZO","sourceId":"NxOYiKCqcuAHVRCj","book":"Pathfinder Lost Omens Pathfinder Society Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.translocate","name":"Translocate","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You instantly transport yourself and any items you're wearing and holding from your current space to an unoccupied space within range you can see. If this would bring another creature with you—even if you're carrying it in an extradimensional container—the spell is lost.\n\nHeightened (5th) The range increases to 1 mile. You don't need to be able to see your destination, as long as you have been there in the past and know its relative location and distance from you. You are then temporarily immune for 1 hour.","source":{"provider":"PAIZO","sourceId":"VlNcjmYyu95vOUe8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.transmigrate","name":"Transmigrate","kind":"RITUAL","rank":4,"rarity":"UNIQUE","traits":["healing"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"heron feathers, incense, and specially prepared sakaki wood"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"the PCs","area":null},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion","secondaryChecks":"Crafting, Nature, Society, or Willowshore Lore","secondaryCasters":2},"description":"","source":{"provider":"PAIZO","sourceId":"8Lk9K3tRnV68MQPW","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.travelers-transit","name":"Traveler's Transit","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You add power to your muscles, allowing you to swim or climb walls with ease. When you Cast this Spell, you gain either a climb Speed or a swim Speed. The Speed is equal to your land Speed.\n\nHeightened (5th) You can choose to gain a fly Speed.","source":{"provider":"PAIZO","sourceId":"LrhTFHUtSS9ahogL","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tricksters-feathers","name":"Trickster's Feathers","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","illusion","manipulate","mythic","visual"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure four magic feathers, each with the potential to hold a single illusory guise. These feathers have negligible Bulk and remain potent for the duration. As an Interact action, you can place one of these feathers into your hair or cap, or remove an already donned feather. When worn in this way, the feather causes you to appear as another creature of the same body shape, and with roughly similar height (within 6 inches) and weight (within 50 pounds), as yourself. The disguise is typically good enough to hide your identity but not to impersonate a specific individual. This disguise also changes your voice and scent, but it doesn't disguise your mannerisms or behavior. You can change the appearance of your clothing and worn items, such as making your armor look like a dress. Held items are unaffected, and any worn item you remove returns to its true appearance.\n\nWhen you don a feather for the first time, you determine the illusory appearance that feather grants you, selecting the ancestry, age, gender, attire, and other visual features. For the duration, this feather is linked to that disguise. Wearing it in your hair or hat always imparts the linked appearance. Selecting a feather's appearance for the first time counts as setting up a disguise for the use of Deception; attempt this Deception check at mythic proficiency.\n\nYou can only wear one feather at a time. When you remove a feather, you revert to your true appearance. If you give a feather to another creature, it can no longer impart a disguise.","source":{"provider":"PAIZO","sourceId":"2wT21v3NjLXdmE5W","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tricksters-twin","name":"Trickster's Twin","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","illusion","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You rarely settle for being in just one place. Choose a location within 100 feet of the target that the target can see. You create an illusion of yourself there that only it can see and that mimics all your actions. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target believes you're in the designated location and can't see you in your actual location. The target automatically disbelieves the illusion when you use an action that doesn't make sense in the illusion's position, or if the target attacks, touches, Seeks, or otherwise engages with the illusion. If you use a hostile action against the target, the spell ends.\n\nFailure As success, but the target must succeed at a Will save to disbelieve the illusion when one of the listed events occurs.\n\nCritical Failure As success, but the target must critically succeed at a Will save to disbelieve when one of the listed events occurs.","source":{"provider":"PAIZO","sourceId":"ZhLYJlOZzUB1OKoe","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.umbral-graft","name":"Umbral Graft","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You reflect a spell into a shadowy version of itself, in the process depleting the power of the initial spell. During umbral graft's duration, you can use the Steal action to attempt to abscond with spells affecting a foe instead of stealing an item. You can also make one attempt to Steal as part of Casting umbral graft. If you succeed at your check to Steal a spell, randomly determine a spell affecting the foe that has a target entry. That spell ceases to affect the target, and you can either cause the spell to affect you or store it in your shadow. If your attempt to Steal was a critical success, you automatically steal the spell if its rank is equal to or lower than umbral graft. If it was a success, you automatically steal it if its rank is lower than umbral graft. If you succeeded, but the spell's rank was too high to steal automatically, you must attempt a counteract check to see if you steal the spell. You know what the spell is as soon as you steal it. If you store it, you can transfer it to a willing creature as a single action that has the manipulate trait. The spell lasts for its remaining duration, to a maximum of 1 minute, and any time you keep it stored subtracts from its duration normally. The spell gains the shadow trait.\n\nYou can't steal constant innate spells that are always active on a creature, such as a choral angel's constant tongues, or innate spells that have special restrictions that remove their ability to target other creatures, such as an imp's invisibility. At the GM's discretion, you might not be able to steal innate spells with other unusual modifications to the base spell.\n\nAs normal, you can Steal only from a target within your reach. Once you've stolen a spell, you can't attempt to Steal more spells, nor can you choose not to take a spell if you succeed at your Thievery check. When you cast umbral graft, any spells you stole with a previous umbral graft end even if their duration hasn't elapsed. If you're affected by both umbral graft and umbral extraction, you make the choice whether to steal a spell slot, an active spell, or an item each time you Steal.","source":{"provider":"PAIZO","sourceId":"juzb53CW6Uzz5pFY","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfettered-movement","name":"Unfettered Movement","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature touched","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You repel effects that would hinder a creature or slow its movement. While under this spell's effect, the target ignores effects that would give them a circumstance penalty to Speed. When they attempt to an effect that has them , , or , they automatically succeed unless the effect is magical and of a higher rank than the unfettered movement spell.","source":{"provider":"PAIZO","sourceId":"aqRYNoSvxsVfqglH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unity","name":"Unity","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","fortune"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"each ally targeted by the triggering spell","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You and 1 or more allies within range are targeted by a spell or ability that allows a saving throw.\n\nYou put up a united defense. Each ally can use your saving throw modifier instead of its own against the triggering spell. Each ally decides individually which modifier to use.","source":{"provider":"PAIZO","sourceId":"tYLBjOTvBVn9JtRb","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unsettling-knowledge","name":"Unsettling Knowledge","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus","linguistic","mental","wood"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You share a piece of hidden knowledge with a creature that is both upsetting and intriguing. When you Cast this Spell, choose Arcana, Nature, Occultism, Religion, or Society as the focus of this knowledge. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target is by the knowledge you shared for 1 round.\n\nFailure The target is fascinated by the knowledge for 1 minute. The target can end this fascination early by attempting a skill check to Recall Knowledge to understand the knowledge using the chosen skill (using your spell DC as the DC); regardless of the result, the target becomes Frightened 2, but if they failed the check, they can't reduce their frightened condition below 1 for the remainder of the spell's duration.\n\nCritical Failure As failure, but the target becomes Frightened 3 if they attempt to Recall Knowledge.","source":{"provider":"PAIZO","sourceId":"iAmHJbFN3lOoOkNG","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
